window.BIO_CARDS=[{"id":"t1-0","n":1,"c":"Kapittel 1","k":"Begrep","f":"Biologi","b":"Læren om alt levende; studiet av levende organismer og forholdet deres til hverandre og miljøet.","u":"kapittel-1.html"},{"id":"t1-1","n":1,"c":"Kapittel 1","k":"Begrep","f":"Anatomi","b":"Bygningen til en organisme.","u":"kapittel-1.html"},{"id":"t1-2","n":1,"c":"Kapittel 1","k":"Begrep","f":"Fysiologi","b":"Funksjonen til organismens deler og prosesser.","u":"kapittel-1.html"},{"id":"t1-3","n":1,"c":"Kapittel 1","k":"Begrep","f":"Homeostase","b":"Et tilnærmet konstant indre miljø i cellene og kroppen, opprettholdt av reguleringsmekanismer.","u":"kapittel-1.html"},{"id":"t1-4","n":1,"c":"Kapittel 1","k":"Begrep","f":"Individ","b":"En enkelt, mer eller mindre selvstyrende organisme. Hos encellede er individet én celle.","u":"kapittel-1.html"},{"id":"t1-5","n":1,"c":"Kapittel 1","k":"Begrep","f":"Organisme","b":"Fra gresk *organon* – organ, instrument, verktøy. En levende enhet bygd opp av én eller flere celler.","u":"kapittel-1.html"},{"id":"t1-6","n":1,"c":"Kapittel 1","k":"Begrep","f":"Hypotese","b":"En mulig forklaring som kan testes gjennom systematiske forsøk.","u":"kapittel-1.html"},{"id":"t1-7","n":1,"c":"Kapittel 1","k":"Begrep","f":"Teori","b":"Hypoteser som er testet mange nok ganger i uavhengige forsøk, og som fagfeltet støtter.","u":"kapittel-1.html"},{"id":"t1-8","n":1,"c":"Kapittel 1","k":"Begrep","f":"Deduksjon","b":"Logiske slutninger steg for steg, fra hypotese til testbar forutsigelse.","u":"kapittel-1.html"},{"id":"t1-9","n":1,"c":"Kapittel 1","k":"Begrep","f":"Induksjon","b":"Å trekke en generell slutning ut fra et antall observasjoner eller forsøk.","u":"kapittel-1.html"},{"id":"t1-10","n":1,"c":"Kapittel 1","k":"Begrep","f":"Feilkilde","b":"Faktor som gjør resultatet av et forsøk usikkert, for eksempel ulik temperatur, vannmengde eller tolkning.","u":"kapittel-1.html"},{"id":"t1-11","n":1,"c":"Kapittel 1","k":"Begrep","f":"Biotop","b":"Levestedet til dyr og planter som naturlig lever sammen.","u":"kapittel-1.html"},{"id":"t1-12","n":1,"c":"Kapittel 1","k":"Begrep","f":"Økosystem","b":"Geografisk avgrenset område med alle abiotiske og biotiske faktorer som påvirker hverandre; inneholder flere biotoper.","u":"kapittel-1.html"},{"id":"t1-13","n":1,"c":"Kapittel 1","k":"Begrep","f":"Abiotiske faktorer","b":"Ikke-levende miljøfaktorer som lys, temperatur, vann, pH og næringsstoffer.","u":"kapittel-1.html"},{"id":"t1-14","n":1,"c":"Kapittel 1","k":"Begrep","f":"Biotiske faktorer","b":"Levende miljøfaktorer som mat, konkurranse, predasjon og parasitter.","u":"kapittel-1.html"},{"id":"t1-15","n":1,"c":"Kapittel 1","k":"Begrep","f":"Binominal navnsetting","b":"Tonavnsystemet til Linné: *Slekt art*, skrevet i kursiv med stor forbokstav i slektsnavnet.","u":"kapittel-1.html"},{"id":"t1-16","n":1,"c":"Kapittel 1","k":"Begrep","f":"Evolusjonsteori","b":"Vitenskapelig forklaring på hvordan arter har oppstått og utviklet seg.","u":"kapittel-1.html"},{"id":"t1-17","n":1,"c":"Kapittel 1","k":"Begrep","f":"Bioinformatikk","b":"Tolkning av store biologiske datasett, ofte genetiske, med statistiske verktøy.","u":"kapittel-1.html"},{"id":"t1-18","n":1,"c":"Kapittel 1","k":"Begrep","f":"Biologisk modellering","b":"Datasimuleringer og statistiske modeller som brukes til å forutsi utvikling, risiko og konsekvenser.","u":"kapittel-1.html"},{"id":"t1-19","n":1,"c":"Kapittel 1","k":"Begrep","f":"Virus","b":"Arvestoff pakket inn i et proteinskall. Trenger en vertscelle for å formere seg og regnes ikke som levende.","u":"kapittel-1.html"},{"id":"r1-0","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hva er biologi?","b":"Biologi er læren om alt levende: studiet av levende organismer og hvordan de forholder seg til hverandre og til miljøet sitt. Ordet kommer fra gresk *bios* (liv) og *logos* (lære).","u":"kapittel-1.html"},{"id":"r1-1","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Nevn noen fagfelter innenfor biologien.","b":"Cellebiologi, molekylærbiologi, mikrobiologi, genetikk, botanikk, mykologi, zoologi, økologi, evolusjonsbiologi og marinbiologi.","u":"kapittel-1.html"},{"id":"r1-2","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hva mener vi med binominal navnsetting?","b":"Tonavnsystemet Linné innførte: hver art får et vitenskapelig navn satt sammen av slektsnavn og artsnavn, for eksempel *Hepatica nobilis*. Navnet kursiveres, og slektsnavnet skrives med stor forbokstav.","u":"kapittel-1.html"},{"id":"r1-3","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hva er Darwin kjent for?","b":"Han grunnla den moderne evolusjonsteorien (1859), basert på blant annet observasjoner av finker på Galápagos. Han viste at arter utvikler seg gjennom tilpasning og naturlig utvalg, og at artene utvikler seg sammen i næringskjeder.","u":"kapittel-1.html"},{"id":"r1-4","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Nevn noen viktige oppdagelser innenfor biologien.","b":"Hooke som så celler (1665), Linnés navnsystem (1700-tallet), Mendels arvelover (1866), navnet kromosomer (1888), Darwins evolusjonsteori (1859), Watson og Cricks DNA-struktur (1953), genteknologi fra 1970-årene og sekvenseringen av menneskets genom i 1999.","u":"kapittel-1.html"},{"id":"r1-5","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hva betyr ordet organisme?","b":"Det kommer fra gresk *organismos* og *organon*, som betyr organ, instrument og verktøy.","u":"kapittel-1.html"},{"id":"r1-6","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hvordan definerer du individ?","b":"Et individ er en enkelt organisme – en mer eller mindre autonom, selvstyrende enhet. I det biologiske hierarkiet ligger individet mellom cellen og populasjonen. Hos encellede organismer er individet lik enkeltcellen.","u":"kapittel-1.html"},{"id":"r1-7","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hvilken inndeling bruker vi i det biologiske hierarkiet?","b":"Økosystem – samfunn – populasjon – art – individ – organsystem – organ – vev – celle.","u":"kapittel-1.html"},{"id":"r1-8","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hva er felles for alle organismenes celler?","b":"De er omgitt av en cellemembran, de har arvestoffet DNA, og de har organeller eller cellestrukturer som ligger i cellevæsken (cytosol).","u":"kapittel-1.html"},{"id":"r1-9","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Forklar hva livsprosessene går ut på.","b":"De sju livsprosessene er vekst og utvikling, fordøyelse og næringsopptak, celleånding og gassutveksling, ekskresjon, reaksjon på stimuli, bevegelse og formering. Sammen sørger de for at organismen får energi og byggesteiner, kvitter seg med avfall, reagerer på omgivelsene og fører genene videre.","u":"kapittel-1.html"},{"id":"r1-10","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hvorfor regner vi ikke virus som levende?","b":"Virus har verken eget stoffskifte, organeller eller celleoppbygning. De er arvestoff i et proteinskall og kan bare formere seg inne i en vertscelle.","u":"kapittel-1.html"},{"id":"r1-11","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Forklar hva som kjennetegner hypotetisk-deduktiv metode og induktiv metode.","b":"Hypotetisk-deduktiv metode kjennetegnes ved systematisk testing av én eller flere hypoteser: observasjon → hypotese → forsøk → bekreftet eller avkreftet. Induktiv metode bygger på kartlegging og observasjon, der man trekker en generell slutning ut fra mange enkeltobservasjoner.","u":"kapittel-1.html"},{"id":"r1-12","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hva er forskjellen på en hypotese og en teori?","b":"En hypotese er en mulig forklaring som ennå ikke er testet godt nok. En teori er hypoteser som er testet mange ganger i uavhengige forsøk, og som støttes bredt i fagfeltet. Teorier dreier seg gjerne om større problemstillinger, som evolusjonsteorien.","u":"kapittel-1.html"},{"id":"r1-13","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hva er en feilkilde?","b":"En faktor som gjør resultatet usikkert fordi den påvirker forsøket uten å være kontrollert – for eksempel ulik vannmengde, temperatur, lys, frøkvalitet eller ulik tolkning av observasjonene.","u":"kapittel-1.html"},{"id":"r1-14","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hva er nytten av å drive feltarbeid?","b":"Du øver på å undersøke og registrere det du observerer, får dybdekunnskap om et bestemt område, og lærer å måle abiotiske og biotiske faktorer og se sammenhengene som forklarer det biologiske mangfoldet.","u":"kapittel-1.html"},{"id":"r1-15","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Forklar forskjellen på et økosystem og en biotop.","b":"En biotop er levestedet til arter som naturlig lever sammen, for eksempel granskog. Et økosystem er arealmessig større, inneholder flere biotoper og omfatter både abiotiske og biotiske faktorer – for eksempel barskogen på Østlandet.","u":"kapittel-1.html"},{"id":"r1-16","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Hvordan kan biologisk modellering være et nyttig hjelpemiddel?","b":"Modellering bruker innsamlede data i statistiske modeller. Ved å endre én eller flere faktorer kan man simulere hva som skjer framover, og beregne miljørisiko og konsekvenser av inngrep før de gjennomføres.","u":"kapittel-1.html"},{"id":"r1-17","n":1,"c":"Kapittel 1","k":"Repetisjon","f":"Nevn noen eksempler på hva man kan bruke biologisk modellering til.","b":"Å forutsi klimaendringer, artsutbredelse, endringer i økosystemer og miljøbelastningen ved naturinngrep, og å tolke store genetiske datasett i bioinformatikk.","u":"kapittel-1.html"},{"id":"t2-0","n":2,"c":"Kapittel 2","k":"Begrep","f":"Taksonomi","b":"Læren om navnsetting og klassifisering av organismer.","u":"kapittel-2.html"},{"id":"t2-1","n":2,"c":"Kapittel 2","k":"Begrep","f":"Binominal navnsetting","b":"Tonavnsystemet *Slekt art*, innført av Linné.","u":"kapittel-2.html"},{"id":"t2-2","n":2,"c":"Kapittel 2","k":"Begrep","f":"Biologisk artsbegrep","b":"Individer av motsatt kjønn hører til samme art når de kan få fruktbart avkom.","u":"kapittel-2.html"},{"id":"t2-3","n":2,"c":"Kapittel 2","k":"Begrep","f":"Morfologisk artsbegrep","b":"Individer med de samme synlige karaktertrekkene tilhører samme art.","u":"kapittel-2.html"},{"id":"t2-4","n":2,"c":"Kapittel 2","k":"Begrep","f":"Fylogenetisk artsbegrep","b":"Arten defineres ut fra plasseringen i et slektskapstre; artsdannelse er en evolusjonær prosess.","u":"kapittel-2.html"},{"id":"t2-5","n":2,"c":"Kapittel 2","k":"Begrep","f":"Underart","b":"Viltlevende gruppe som skiller seg utseendemessig fra hovedarten, men kan krysses med den, for eksempel svalbardrein.","u":"kapittel-2.html"},{"id":"t2-6","n":2,"c":"Kapittel 2","k":"Begrep","f":"Rase","b":"Brukes om varianter av husdyr, for eksempel hunderaser.","u":"kapittel-2.html"},{"id":"t2-7","n":2,"c":"Kapittel 2","k":"Begrep","f":"Sort","b":"Brukes om dyrkede plantevarianter, for eksempel potet- og eplesorter.","u":"kapittel-2.html"},{"id":"t2-8","n":2,"c":"Kapittel 2","k":"Begrep","f":"Bestemmelsesnøkkel","b":"Hjelpemiddel bygd på enten-eller-spørsmål som fører fram til artsnavnet.","u":"kapittel-2.html"},{"id":"t2-9","n":2,"c":"Kapittel 2","k":"Begrep","f":"DNA-strekkoding","b":"Artsbestemmelse ved å sekvensere en bestemt DNA-bit som er unik for arten.","u":"kapittel-2.html"},{"id":"t2-10","n":2,"c":"Kapittel 2","k":"Begrep","f":"Miljø-DNA (eDNA)","b":"DNA som organismer avgir til vann og jord, og som analyseres for å kartlegge mangfold.","u":"kapittel-2.html"},{"id":"t2-11","n":2,"c":"Kapittel 2","k":"Begrep","f":"Ribosomanalyse","b":"Sammenlikning av ribosomenes underenheter for å avgjøre slektskap.","u":"kapittel-2.html"},{"id":"t2-12","n":2,"c":"Kapittel 2","k":"Begrep","f":"Domene","b":"Det høyeste klassifikasjonsnivået: bakterier, arker og eukaryoter.","u":"kapittel-2.html"},{"id":"t2-13","n":2,"c":"Kapittel 2","k":"Begrep","f":"Rike","b":"Nivået under domene: bakterier, arker, protister, sopper, planter og dyr.","u":"kapittel-2.html"},{"id":"t2-14","n":2,"c":"Kapittel 2","k":"Begrep","f":"Prokaryot","b":"Celle uten cellekjerne; DNA-et ligger fritt i cytoplasmaet.","u":"kapittel-2.html"},{"id":"t2-15","n":2,"c":"Kapittel 2","k":"Begrep","f":"Eukaryot","b":"Celle med cellekjerne omgitt av en dobbel kjernemembran.","u":"kapittel-2.html"},{"id":"t2-16","n":2,"c":"Kapittel 2","k":"Begrep","f":"Mycel","b":"Nettverk av trådformede hyfer hos sopp.","u":"kapittel-2.html"},{"id":"t2-17","n":2,"c":"Kapittel 2","k":"Begrep","f":"Mykorrhiza","b":"Mutualistisk samliv mellom sopphyfer og planterøtter.","u":"kapittel-2.html"},{"id":"t2-18","n":2,"c":"Kapittel 2","k":"Begrep","f":"Mutualisme","b":"Symbiose der begge partene har utbytte av samlivet.","u":"kapittel-2.html"},{"id":"t2-19","n":2,"c":"Kapittel 2","k":"Begrep","f":"Lav","b":"Symbiose mellom sopp og grønnalge eller blågrønnbakterie; brukes som forurensningsindikator.","u":"kapittel-2.html"},{"id":"t2-20","n":2,"c":"Kapittel 2","k":"Begrep","f":"Autotrof","b":"Organisme som bygger organiske forbindelser av uorganiske, ved fotosyntese eller kjemisk energi.","u":"kapittel-2.html"},{"id":"t2-21","n":2,"c":"Kapittel 2","k":"Begrep","f":"Heterotrof","b":"Organisme som må ta opp organiske molekyler fra andre organismer.","u":"kapittel-2.html"},{"id":"r2-0","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvordan lages et vitenskapelig artsnavn?","b":"Det består av slektsnavn og artsnavn etter mønsteret *Slekt art*. Navnet kursiveres, og slektsnavnet får stor forbokstav, for eksempel *Taraxacum officinale*.","u":"kapittel-2.html"},{"id":"r2-1","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hva er Hepatica nobilis?","b":"Det latinske navnet på blåveis. *Hepatica* kommer av gresk *hepar* (lever) og viser til bladformen, mens *nobilis* betyr flott eller staselig.","u":"kapittel-2.html"},{"id":"r2-2","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvilke tre artsbegreper brukes til vanlig?","b":"Det biologiske (fruktbart avkom), det morfologiske (synlige karaktertrekk) og det fylogenetiske eller evolusjonistiske (plassering i slektskapstreet).","u":"kapittel-2.html"},{"id":"r2-3","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvorfor fungerer ikke det biologiske artsbegrepet for arter som formerer seg ukjønnet?","b":"Begrepet bygger på at individer av motsatt kjønn kan få fruktbart avkom. Bakterier og andre som deler seg ukjønnet, har ikke kjønnet formering, og kriteriet kan ikke brukes.","u":"kapittel-2.html"},{"id":"r2-4","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvorfor regnes esel og hest som to arter?","b":"De kan få avkom, men muldyr og mulesel er sterile. Avkommet er altså ikke forplantningsdyktig, og etter det biologiske artsbegrepet er de derfor to arter.","u":"kapittel-2.html"},{"id":"r2-5","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hva er en bestemmelsesnøkkel?","b":"Et hjelpemiddel bygd på enten-eller-spørsmål om synlige kjennetegn. Du svarer deg gjennom nøkkelen til du ender på et artsnavn.","u":"kapittel-2.html"},{"id":"r2-6","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvordan kan du skille en fiskemåke fra en krykkje?","b":"Begge har grå rygg, men fiskemåken har gulgrønne bein, mens krykkja har svarte bein og svarte vingespisser.","u":"kapittel-2.html"},{"id":"r2-7","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvorfor brukes genetiske metoder mer og mer til artsbestemmelse?","b":"De er raskere, billigere og sikrere enn tradisjonell morfologi, de virker på alle livsstadier og på fragmenter, og de skiller arter som ser like ut. For mikroskopiske arter er genetikk ofte eneste mulighet.","u":"kapittel-2.html"},{"id":"r2-8","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvordan kan en genetisk analyse brukes til å avgjøre om to individer er av samme art?","b":"Man sekvenserer den samme DNA-biten hos begge, for eksempel cytokrom C oksidase-genet i mitokondriene, og sammenlikner sekvensene. Artsspesifikke forskjeller viser om de tilhører samme art.","u":"kapittel-2.html"},{"id":"r2-9","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hva går ribosomanalyse ut på?","b":"Man sammenlikner oppbygningen av ribosomenes underenheter. Prokaryote ribosomer skiller seg fra eukaryote, og størrelsene varierer mellom arter, slik at slektskap kan bekreftes eller avkreftes.","u":"kapittel-2.html"},{"id":"r2-10","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hva er et klassifikasjonssystem?","b":"Et enhetlig og logisk system for å sortere artene i grupper og gi dem navn, også kalt et taksonomisk system.","u":"kapittel-2.html"},{"id":"r2-11","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvor mange domener og riker finnes det?","b":"Tre domener (bakterier, arker og eukaryoter) og seks riker (bakterier, arker, protister, planter, sopper og dyr).","u":"kapittel-2.html"},{"id":"r2-12","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvilke nivåer finnes i klassifikasjonssystemet?","b":"Domene, rike, rekke (divisjon hos planter), klasse, orden, familie, slekt og art.","u":"kapittel-2.html"},{"id":"r2-13","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hva er forskjellene på prokaryoter og eukaryoter?","b":"Prokaryoter mangler cellekjerne og membrandekte organeller, og DNA-et ligger fritt i cytoplasmaet. Eukaryoter har cellekjerne med dobbel kjernemembran, mange organeller og er mye større celler.","u":"kapittel-2.html"},{"id":"r2-14","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hvilke riker består av prokaryote organismer?","b":"Bakterier og arker.","u":"kapittel-2.html"},{"id":"r2-15","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Hva er penicillin og cyclosporin, og hva bruker vi dem til?","b":"Begge er stoffer fra sopp. Penicillin kommer fra *Penicillium* og brukes som antibiotikum fordi det ødelegger bakterienes cellevegg. Cyclosporin kommer opprinnelig fra muggsoppen *Tolypocladium inflatum* og demper immunforsvaret, slik at transplanterte organer ikke avstøtes.","u":"kapittel-2.html"},{"id":"r2-16","n":2,"c":"Kapittel 2","k":"Repetisjon","f":"Gi noen kjennetegn ved protister, sopp, planter og dyr.","b":"Protister: eukaryote, oftest encellede, svært variable – amøber, planktonalger og store tangarter. Sopp: eukaryote, heterotrofe, cellevegg av kitin, formerer seg med sporer. Planter: flercellede og fotoautotrofe med cellevegg av cellulose. Dyr: flercellede, heterotrofe og oftest bevegelige.","u":"kapittel-2.html"},{"id":"t3-0","n":3,"c":"Kapittel 3","k":"Begrep","f":"Prokaryot celle","b":"Celle uten cellekjerne og uten membrandekte organeller.","u":"kapittel-3.html"},{"id":"t3-1","n":3,"c":"Kapittel 3","k":"Begrep","f":"Eukaryot celle","b":"Celle med cellekjerne omgitt av dobbel kjernemembran og med mange organeller.","u":"kapittel-3.html"},{"id":"t3-2","n":3,"c":"Kapittel 3","k":"Begrep","f":"Cytoplasma","b":"Hele området innenfor cellemembranen, utenom cellekjernen.","u":"kapittel-3.html"},{"id":"t3-3","n":3,"c":"Kapittel 3","k":"Begrep","f":"Cytosol","b":"Cellevæsken i cytoplasmaet, opptil 90 % vann.","u":"kapittel-3.html"},{"id":"t3-4","n":3,"c":"Kapittel 3","k":"Begrep","f":"Organell","b":"Struktur i cytoplasmaet omgitt av én eller flere membraner, med egen funksjon.","u":"kapittel-3.html"},{"id":"t3-5","n":3,"c":"Kapittel 3","k":"Begrep","f":"Enzym","b":"Protein som virker som katalysator og får kjemiske reaksjoner til å gå raskere ved lav temperatur.","u":"kapittel-3.html"},{"id":"t3-6","n":3,"c":"Kapittel 3","k":"Begrep","f":"Plasmid","b":"Lite, ringformet DNA-molekyl hos bakterier, ofte med gener for antibiotikaresistens.","u":"kapittel-3.html"},{"id":"t3-7","n":3,"c":"Kapittel 3","k":"Begrep","f":"Flagell","b":"Lang utbuktning fra celleoverflaten som gir bevegelse.","u":"kapittel-3.html"},{"id":"t3-8","n":3,"c":"Kapittel 3","k":"Begrep","f":"Cilier","b":"Korte, hårliknende utbuktninger som gir bevegelse eller flytter væske over overflaten.","u":"kapittel-3.html"},{"id":"t3-9","n":3,"c":"Kapittel 3","k":"Begrep","f":"Kromosom","b":"DNA-molekyl pakket rundt proteiner.","u":"kapittel-3.html"},{"id":"t3-10","n":3,"c":"Kapittel 3","k":"Begrep","f":"Diploid","b":"Celle med parvise kromosomer (2n), som kroppscellene våre.","u":"kapittel-3.html"},{"id":"t3-11","n":3,"c":"Kapittel 3","k":"Begrep","f":"Haploid","b":"Celle med enkeltkromosomer (n), som kjønnscellene.","u":"kapittel-3.html"},{"id":"t3-12","n":3,"c":"Kapittel 3","k":"Begrep","f":"Transkripsjon","b":"Kopiering av et gen fra DNA til RNA.","u":"kapittel-3.html"},{"id":"t3-13","n":3,"c":"Kapittel 3","k":"Begrep","f":"mRNA","b":"Budbringer-RNA; kopien av ett gen som brukes som oppskrift i proteinsyntesen.","u":"kapittel-3.html"},{"id":"t3-14","n":3,"c":"Kapittel 3","k":"Begrep","f":"Ribosom","b":"Struktur av rRNA og proteiner der aminosyrer kobles sammen til polypeptider.","u":"kapittel-3.html"},{"id":"t3-15","n":3,"c":"Kapittel 3","k":"Begrep","f":"Mitokondrie","b":"Organell med dobbel membran der celleåndingen foregår og ATP dannes.","u":"kapittel-3.html"},{"id":"t3-16","n":3,"c":"Kapittel 3","k":"Begrep","f":"ATP","b":"Adenosintrifosfat, cellens viktigste energibærer.","u":"kapittel-3.html"},{"id":"t3-17","n":3,"c":"Kapittel 3","k":"Begrep","f":"Cytoskjelett","b":"Nettverk av proteinfibrer som stiver opp cellen, holder organellene på plass og fungerer som transportvei.","u":"kapittel-3.html"},{"id":"t3-18","n":3,"c":"Kapittel 3","k":"Begrep","f":"Endomembransystemet","b":"Kjernemembran, ER, golgiapparat, lysosomer, vakuoler og cellemembran som samarbeider om transport.","u":"kapittel-3.html"},{"id":"t3-19","n":3,"c":"Kapittel 3","k":"Begrep","f":"Endoplasmatisk nettverk (ER)","b":"Membransystem der stoffer lages, fraktes og lagres. Ru ER har ribosomer, glatt ER har ikke.","u":"kapittel-3.html"},{"id":"t3-20","n":3,"c":"Kapittel 3","k":"Begrep","f":"Golgiapparatet","b":"Stabler av blærer som sorterer, omdanner og merker proteiner og lipider.","u":"kapittel-3.html"},{"id":"t3-21","n":3,"c":"Kapittel 3","k":"Begrep","f":"Lysosom","b":"Blære med om lag femti nedbrytende enzymer som virker best ved pH rundt 5.","u":"kapittel-3.html"},{"id":"t3-22","n":3,"c":"Kapittel 3","k":"Begrep","f":"Autofagi","b":"Cellens «selvspising», der ødelagte deler brytes ned og gjenvinnes.","u":"kapittel-3.html"},{"id":"t3-23","n":3,"c":"Kapittel 3","k":"Begrep","f":"Peroksisom","b":"Organell som bryter ned fettsyrer og danner hydrogenperoksid, som katalase spalter.","u":"kapittel-3.html"},{"id":"t3-24","n":3,"c":"Kapittel 3","k":"Begrep","f":"Vakuole","b":"Stort væskefylt cellesaftrom i planteceller som gir turgortrykk og lagrer stoffer.","u":"kapittel-3.html"},{"id":"t3-25","n":3,"c":"Kapittel 3","k":"Begrep","f":"Turgortrykk","b":"Det indre vanntrykket i en plantecelle som holder planten saftspent.","u":"kapittel-3.html"},{"id":"t3-26","n":3,"c":"Kapittel 3","k":"Begrep","f":"Kloroplast","b":"Organell med klorofyll der fotosyntesen foregår.","u":"kapittel-3.html"},{"id":"t3-27","n":3,"c":"Kapittel 3","k":"Begrep","f":"Lignin","b":"Kompleks forbindelse som forsterker celleveggen og gjør at planten tåler trykk.","u":"kapittel-3.html"},{"id":"t3-28","n":3,"c":"Kapittel 3","k":"Begrep","f":"Endosymbiose","b":"At en organisme lever inni en annen i et symbioseforhold.","u":"kapittel-3.html"},{"id":"t3-29","n":3,"c":"Kapittel 3","k":"Begrep","f":"Endosymbioseteorien","b":"Teorien om at mitokondrier og kloroplaster stammer fra opptatte prokaryote celler.","u":"kapittel-3.html"},{"id":"r3-0","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hvilke seks riker deler vi alle organismer inn i?","b":"Bakterier, arker, protister, sopper, planter og dyr.","u":"kapittel-3.html"},{"id":"r3-1","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hva er forskjellene på prokaryoter og eukaryoter?","b":"Prokaryoter mangler cellekjerne og membrandekte organeller; DNA-et ligger fritt. Eukaryoter har cellekjerne med dobbel kjernemembran, mange organeller og betydelig større celler.","u":"kapittel-3.html"},{"id":"r3-2","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hvor mange µm og nm er det i en millimeter?","b":"1 mm = 1000 µm = 1 000 000 nm.","u":"kapittel-3.html"},{"id":"r3-3","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hvor finnes de prokaryote organismene?","b":"Overalt der det finnes fuktighet: i jord, vann, luft, på og i andre organismer, i varme kilder, saltsjøer og dypt nede i fjell.","u":"kapittel-3.html"},{"id":"r3-4","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hvorfor plasserer vi bakterier og arker i to ulike riker?","b":"Fordi forskjellene mellom dem er svært store. De har i stor grad uavhengig evolusjonshistorie, ulik cellevegg og cellemembran, og arkene likner eukaryotene i proteinsyntese og DNA-kopiering.","u":"kapittel-3.html"},{"id":"r3-5","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hvordan kan bakterier overleve tørke?","b":"De går inn i et sporestadium med en tykk beskyttende vegg som tåler uttørking, og kvikner til når det igjen blir fuktig.","u":"kapittel-3.html"},{"id":"r3-6","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hvilke typer bakterier driver fotosyntese?","b":"Fotoautotrofe bakterier, det vil si blågrønnbakterier (cyanobakterier).","u":"kapittel-3.html"},{"id":"r3-7","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hva slags symbioseform er det mellom oss og tarmbakteriene?","b":"Mutualisme – begge parter har nytte av samlivet.","u":"kapittel-3.html"},{"id":"r3-8","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hva slags art bakterier lever i tarmene våre?","b":"Blant mange andre *Escherichia coli* (E. coli), som er viktig i fordøyelsessystemet.","u":"kapittel-3.html"},{"id":"r3-9","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Har arker cellekjerne?","b":"Nei. Arker er prokaryote og mangler cellekjerne, men DNA-et er pakket tett sammen av små proteiner som likner eukaryotenes.","u":"kapittel-3.html"},{"id":"r3-10","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Bruker vi antibiotika for å drepe arker?","b":"Nei. Arker tåler antibiotika, og det er ikke noe problem, siden ingen kjente arker er sykdomsframkallende.","u":"kapittel-3.html"},{"id":"r3-11","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Gi noen eksempler på hvor vi kan finne arker.","b":"I varme svovelkilder over 100 °C, i saltsjøer som Dødehavet, i oksygenfritt bunnvann, i tarmsystemer, dypt nede i fjell og jord, og i store mengder i havet.","u":"kapittel-3.html"},{"id":"r3-12","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Forklar forskjellene på cytoplasma og cytosol.","b":"Cytoplasma er hele området mellom cellemembranen og cellekjernen, inkludert organellene. Cytosol er selve cellevæsken i cytoplasmaet.","u":"kapittel-3.html"},{"id":"r3-13","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hva er et enzym?","b":"Et protein som virker som katalysator: det får en bestemt kjemisk reaksjon til å gå raskere uten at det trengs høy temperatur eller mye energi.","u":"kapittel-3.html"},{"id":"r3-14","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hvilke av organellene er omgitt av en dobbel membran?","b":"Cellekjernen, mitokondriene og kloroplastene.","u":"kapittel-3.html"},{"id":"r3-15","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hva foregår i mitokondriene?","b":"Aerob celleånding: organiske molekyler fra maten spaltes ved hjelp av oksygen, og energien lagres som ATP. Det dannes karbondioksid og vann.","u":"kapittel-3.html"},{"id":"r3-16","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hva foregår i kloroplastene?","b":"Fotosyntesen: lysenergi bindes som kjemisk energi, og vann og karbondioksid blir til glukose og oksygen.","u":"kapittel-3.html"},{"id":"r3-17","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Forklar hvilke organeller og prosesser som bindes sammen i endomembransystemet.","b":"Kjernemembranen, det endoplasmatiske nettverket, golgiapparatet, lysosomer, vakuoler og cellemembranen. Proteiner lages på ru ER, fraktes i blærer til golgiapparatet der de merkes og sorteres, og sendes videre til andre organeller eller ut av cellen.","u":"kapittel-3.html"},{"id":"r3-18","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hva inneholder en vakuole?","b":"Cellesaft med vann, lagrede stoffer, fargestoffer, giftstoffer og avfallsprodukter fra stoffskiftet.","u":"kapittel-3.html"},{"id":"r3-19","n":3,"c":"Kapittel 3","k":"Repetisjon","f":"Hvordan forklarer endosymbioseteorien at kloroplaster og mitokondrier har dobbel membran?","b":"Den indre membranen stammer fra den prokaryote organismen som ble tatt opp, og den ytre fra cellemembranen til den eukaryote cellen som omsluttet den ved endocytose.","u":"kapittel-3.html"},{"id":"t4-0","n":4,"c":"Kapittel 4","k":"Begrep","f":"Selektiv permeabilitet","b":"Egenskapen til cellemembranen som gjør at noen stoffer slipper gjennom mens andre stoppes.","u":"kapittel-4.html"},{"id":"t4-1","n":4,"c":"Kapittel 4","k":"Begrep","f":"Lipid","b":"Fellesnavn på fettaktige stoffer som ikke løses i vann.","u":"kapittel-4.html"},{"id":"t4-2","n":4,"c":"Kapittel 4","k":"Begrep","f":"Triglyserid","b":"Vanlig fett: ett glyserolmolekyl og tre fettsyrer.","u":"kapittel-4.html"},{"id":"t4-3","n":4,"c":"Kapittel 4","k":"Begrep","f":"Fosfolipid","b":"Lipid der én fettsyre er byttet ut med fosfat; byggesteinen i cellemembranen.","u":"kapittel-4.html"},{"id":"t4-4","n":4,"c":"Kapittel 4","k":"Begrep","f":"Hydrofil","b":"Vannelskende; polare molekyler og ioner.","u":"kapittel-4.html"},{"id":"t4-5","n":4,"c":"Kapittel 4","k":"Begrep","f":"Hydrofob","b":"Vannskyende og fettløselig; upolare molekyler.","u":"kapittel-4.html"},{"id":"t4-6","n":4,"c":"Kapittel 4","k":"Begrep","f":"Polar","b":"Molekyl med overskudd eller underskudd av elektroner i deler av molekylet, altså med ladning.","u":"kapittel-4.html"},{"id":"t4-7","n":4,"c":"Kapittel 4","k":"Begrep","f":"Upolar","b":"Molekyl uten ladning.","u":"kapittel-4.html"},{"id":"t4-8","n":4,"c":"Kapittel 4","k":"Begrep","f":"Kolesterol","b":"Lipid i cellemembranen som holder membranen myk eller gjør den stivere.","u":"kapittel-4.html"},{"id":"t4-9","n":4,"c":"Kapittel 4","k":"Begrep","f":"Transportprotein","b":"Protein som går gjennom membranen og frakter bestemte stoffer inn eller ut.","u":"kapittel-4.html"},{"id":"t4-10","n":4,"c":"Kapittel 4","k":"Begrep","f":"Glykoprotein","b":"Protein med karbohydrat festet til seg; viktig for gjenkjenning av celler.","u":"kapittel-4.html"},{"id":"t4-11","n":4,"c":"Kapittel 4","k":"Begrep","f":"Glykolipid","b":"Lipid med karbohydrat festet til seg på membranens utside.","u":"kapittel-4.html"},{"id":"t4-12","n":4,"c":"Kapittel 4","k":"Begrep","f":"Diffusjon","b":"Bevegelse av molekyler fra høy til lav konsentrasjon.","u":"kapittel-4.html"},{"id":"t4-13","n":4,"c":"Kapittel 4","k":"Begrep","f":"Konsentrasjonsgradient","b":"Forskjellen i konsentrasjon mellom to steder.","u":"kapittel-4.html"},{"id":"t4-14","n":4,"c":"Kapittel 4","k":"Begrep","f":"Enkel diffusjon","b":"Passiv transport av små upolare molekyler direkte mellom fosfolipidene.","u":"kapittel-4.html"},{"id":"t4-15","n":4,"c":"Kapittel 4","k":"Begrep","f":"Fasilitert diffusjon","b":"Passiv transport av ioner og polare molekyler gjennom transportproteiner.","u":"kapittel-4.html"},{"id":"t4-16","n":4,"c":"Kapittel 4","k":"Begrep","f":"Osmose","b":"Diffusjon av vann gjennom en selektivt permeabel membran.","u":"kapittel-4.html"},{"id":"t4-17","n":4,"c":"Kapittel 4","k":"Begrep","f":"Akvaporin","b":"Transportprotein som slipper store mengder vann gjennom membranen.","u":"kapittel-4.html"},{"id":"t4-18","n":4,"c":"Kapittel 4","k":"Begrep","f":"Osmotisk trykk","b":"Forskjellen i trykk mot membranen på innsiden og utsiden av cellen.","u":"kapittel-4.html"},{"id":"t4-19","n":4,"c":"Kapittel 4","k":"Begrep","f":"Aktiv transport","b":"Energikrevende transport, oftest mot konsentrasjonsgradienten.","u":"kapittel-4.html"},{"id":"t4-20","n":4,"c":"Kapittel 4","k":"Begrep","f":"Eksocytose","b":"Partikler samles i blærer og tømmes ut gjennom cellemembranen.","u":"kapittel-4.html"},{"id":"t4-21","n":4,"c":"Kapittel 4","k":"Begrep","f":"Endocytose","b":"Cellemembranen folder seg innover og tar opp store partikler i en blære.","u":"kapittel-4.html"},{"id":"r4-0","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Forklar begrepet selektiv permeabilitet.","b":"Cellemembranen er delvis gjennomtrengelig: den slipper noen stoffer gjennom og stopper andre. Slik kontrollerer cellen sitt indre miljø.","u":"kapittel-4.html"},{"id":"r4-1","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hvorfor må alle celler være omgitt av en cellemembran?","b":"Miljøet inni cellen er svært forskjellig fra miljøet utenfor. Membranen avgrenser cellen, beskytter innholdet og styrer transporten inn og ut.","u":"kapittel-4.html"},{"id":"r4-2","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hva er lipider? Gi eksempler.","b":"Fettaktige stoffer som ikke løses i vann: fett (triglyserider), voks, talg, kolesterol og steroider som kjønnshormoner.","u":"kapittel-4.html"},{"id":"r4-3","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Forklar forskjellene på et triglyserid og et fosfolipid.","b":"Begge har et glyserolmolekyl. Triglyseridet har tre fettsyrer, mens fosfolipidet har to fettsyrer og én fosfatgruppe med et organisk molekyl. Fosfatdelen er polar og hydrofil, fettsyrene er upolare og hydrofobe.","u":"kapittel-4.html"},{"id":"r4-4","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Forklar ordene polar, upolar, hydrofob og hydrofil.","b":"Polare molekyler har ladning, upolare har ikke. Hydrofile stoffer er vannløselige og polare, hydrofobe er fettløselige og upolare.","u":"kapittel-4.html"},{"id":"r4-5","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hva skiller cellemembranene i ulike celletyper fra hverandre?","b":"Sammensetningen av fosfolipider, mengden kolesterol, hvilke transportproteiner som finnes, og hvilke glykoproteiner og glykolipider som sitter på utsiden. Røde blodceller har for eksempel andre fosfolipider enn hudceller.","u":"kapittel-4.html"},{"id":"r4-6","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Gi eksempler på stoffer som skal inn i en celle, og stoffer som må ut.","b":"Inn: oksygen, glukose, aminosyrer, ioner, vann og fettsyrer. Ut: karbondioksid, urinstoff og andre avfallsstoffer, og hos kjertelceller hormoner og enzymer.","u":"kapittel-4.html"},{"id":"r4-7","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hva er forskjellen på passiv og aktiv transport?","b":"Passiv transport krever ikke energi og går med konsentrasjonsgradienten. Aktiv transport krever energi fra ATP og går som regel mot gradienten.","u":"kapittel-4.html"},{"id":"r4-8","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hvilke stoffer kan passere gjennom lipidlaget, og hvilke må gjennom transportproteiner?","b":"Små upolare molekyler som O₂ og CO₂ og fettløselige stoffer går rett gjennom. Ioner, polare molekyler som glukose og aminosyrer, og det meste av vannet må gjennom transportproteiner.","u":"kapittel-4.html"},{"id":"r4-9","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Forklar med ord hva enkel diffusjon, fasilitert diffusjon og osmose er.","b":"Enkel diffusjon: små upolare molekyler passerer direkte mellom fosfolipidene. Fasilitert diffusjon: ioner og polare molekyler passerer gjennom transportproteiner, fortsatt uten energi. Osmose: diffusjon av vann gjennom en selektivt permeabel membran, mest gjennom akvaporiner.","u":"kapittel-4.html"},{"id":"r4-10","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hvilken funksjon har akvaporinene?","b":"De er transportproteiner som slipper store mengder vann raskt gjennom membranen – mer enn en milliard molekyler per sekund per akvaporin. Cellen kan regulere antallet etter behov.","u":"kapittel-4.html"},{"id":"r4-11","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hva skjer hvis du lar druer stå på benken i noen uker, og hva skjer om du putter rosiner i vann?","b":"Druene mister vann ved osmose og fordamping, skrumper inn og blir rosiner. Legger du rosiner i vann, er vannkonsentrasjonen høyest utenfor, og vann trenger inn ved osmose slik at de sveller.","u":"kapittel-4.html"},{"id":"r4-12","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hva betyr det at stoffer flytter seg mot en konsentrasjonsgradient?","b":"At de fraktes fra et sted med lav konsentrasjon til et sted med høyere konsentrasjon. Det skjer ikke av seg selv og krever energi.","u":"kapittel-4.html"},{"id":"r4-13","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Blir energi brukt eller produsert ved aktiv transport?","b":"Brukt. Energien kommer fra spalting av ATP til ADP og fosfat.","u":"kapittel-4.html"},{"id":"r4-14","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Gi to eksempler på stoffer som transporteres ved aktiv transport.","b":"Na⁺- og K⁺-ioner i nerveceller, og H⁺-ioner (protoner) over membranene i mitokondrier og kloroplaster. Også aminosyrer og glukose pumpes aktivt i tarm og nyrer.","u":"kapittel-4.html"},{"id":"r4-15","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hva er endocytose og eksocytose?","b":"Endocytose: cellemembranen bukter seg innover og tar opp store partikler i en blære. Eksocytose: blærer inni cellen smelter sammen med cellemembranen og tømmer innholdet ut. Begge krever energi.","u":"kapittel-4.html"},{"id":"r4-16","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hvorfor må cellene i et cellevev samarbeide?","b":"For at vevet skal fungere som en enhet må cellene utveksle næring, ioner og signaler, og koordinere aktiviteten. I hjertet må for eksempel muskelcellene trekke seg sammen samtidig.","u":"kapittel-4.html"},{"id":"r4-17","n":4,"c":"Kapittel 4","k":"Repetisjon","f":"Hvordan foregår kanaltransport hos planter og hos dyr?","b":"Hos planter går mange små kanaler gjennom cellemembran og cellevegg, og de er åpne hele tiden. Hos dyr går kanalene mellom nabocellenes cytoplasma, og de kan åpnes og lukkes etter behov.","u":"kapittel-4.html"},{"id":"t5-0","n":5,"c":"Kapittel 5","k":"Begrep","f":"Mikroorganisme","b":"Bakterier, virus, sopp og parasitter – organismer som er for små til å ses med det blotte øye.","u":"kapittel-5.html"},{"id":"t5-1","n":5,"c":"Kapittel 5","k":"Begrep","f":"Mikrobiom","b":"Samlingen av alle mikroorganismer som lever på og i en organisme.","u":"kapittel-5.html"},{"id":"t5-2","n":5,"c":"Kapittel 5","k":"Begrep","f":"Kolonisering","b":"At mikroorganismer har fast tilhold på kroppen uten å gi sykdom.","u":"kapittel-5.html"},{"id":"t5-3","n":5,"c":"Kapittel 5","k":"Begrep","f":"Infeksjon","b":"Mikroorganismer trenger inn i kroppens vev.","u":"kapittel-5.html"},{"id":"t5-4","n":5,"c":"Kapittel 5","k":"Begrep","f":"Immunitet","b":"Evnen til å stå imot en infeksjon uten å bli syk.","u":"kapittel-5.html"},{"id":"t5-5","n":5,"c":"Kapittel 5","k":"Begrep","f":"Dråpesmitte","b":"Smitte via små væskedråper fra hoste og nys.","u":"kapittel-5.html"},{"id":"t5-6","n":5,"c":"Kapittel 5","k":"Begrep","f":"Kontaktsmitte","b":"Smitte ved direkte kroppskontakt eller via gjenstander.","u":"kapittel-5.html"},{"id":"t5-7","n":5,"c":"Kapittel 5","k":"Begrep","f":"Bakteriofag","b":"Virus som angriper bakterier.","u":"kapittel-5.html"},{"id":"t5-8","n":5,"c":"Kapittel 5","k":"Begrep","f":"Retrovirus","b":"RNA-virus som lager en DNA-kopi av arvestoffet sitt med revers transkriptase, for eksempel hiv.","u":"kapittel-5.html"},{"id":"t5-9","n":5,"c":"Kapittel 5","k":"Begrep","f":"Lytisk vekst","b":"Formering der viruset sprenger vertscellen når de nye viruspartiklene frigjøres.","u":"kapittel-5.html"},{"id":"t5-10","n":5,"c":"Kapittel 5","k":"Begrep","f":"R-tall","b":"Reproduksjonstallet: hvor mange én syk person i gjennomsnitt smitter.","u":"kapittel-5.html"},{"id":"t5-11","n":5,"c":"Kapittel 5","k":"Begrep","f":"Epidemi","b":"Utbrudd av smittsom sykdom i et avgrenset område eller en befolkning.","u":"kapittel-5.html"},{"id":"t5-12","n":5,"c":"Kapittel 5","k":"Begrep","f":"Pandemi","b":"Epidemi som har spredd seg over store deler av verden.","u":"kapittel-5.html"},{"id":"t5-13","n":5,"c":"Kapittel 5","k":"Begrep","f":"Fagocytose","b":"Cellespising: en hvit blodcelle omslutter og bryter ned en mikroorganisme.","u":"kapittel-5.html"},{"id":"t5-14","n":5,"c":"Kapittel 5","k":"Begrep","f":"Makrofag","b":"Stor fagocytt som ligger i vevet og bekjemper infeksjoner.","u":"kapittel-5.html"},{"id":"t5-15","n":5,"c":"Kapittel 5","k":"Begrep","f":"Dendrittisk celle","b":"Fagocytt med utløpere som frakter antigener til lymfeknutene og aktiverer det tilpassede forsvaret.","u":"kapittel-5.html"},{"id":"t5-16","n":5,"c":"Kapittel 5","k":"Begrep","f":"Interferon","b":"Protein fra virusinfiserte celler som varsler nabocellene og hemmer virusformering.","u":"kapittel-5.html"},{"id":"t5-17","n":5,"c":"Kapittel 5","k":"Begrep","f":"Betennelse","b":"Kroppens reaksjon på skade: rødme, hevelse, varme og smerte.","u":"kapittel-5.html"},{"id":"t5-18","n":5,"c":"Kapittel 5","k":"Begrep","f":"Antigen","b":"Fremmed molekyl som immunforsvaret reagerer på.","u":"kapittel-5.html"},{"id":"t5-19","n":5,"c":"Kapittel 5","k":"Begrep","f":"Antistoff","b":"Protein fra plasmaceller som binder seg til et bestemt antigen.","u":"kapittel-5.html"},{"id":"t5-20","n":5,"c":"Kapittel 5","k":"Begrep","f":"Lymfocytt","b":"Hvit blodcelle i det tilpassede forsvaret: B-celler og T-celler.","u":"kapittel-5.html"},{"id":"t5-21","n":5,"c":"Kapittel 5","k":"Begrep","f":"Plasmacelle","b":"B-celle som produserer store mengder antistoffer.","u":"kapittel-5.html"},{"id":"t5-22","n":5,"c":"Kapittel 5","k":"Begrep","f":"Hukommelsescelle","b":"B- eller T-celle som husker et antigen og gir rask reaksjon ved nytt møte.","u":"kapittel-5.html"},{"id":"t5-23","n":5,"c":"Kapittel 5","k":"Begrep","f":"Aktiv immunitet","b":"Kroppen lager selv antistoffer og hukommelsesceller, etter vaksine eller gjennomgått sykdom.","u":"kapittel-5.html"},{"id":"t5-24","n":5,"c":"Kapittel 5","k":"Begrep","f":"Passiv immunitet","b":"Ferdige antistoffer overføres fra et annet individ; virker raskt, men kortvarig.","u":"kapittel-5.html"},{"id":"t5-25","n":5,"c":"Kapittel 5","k":"Begrep","f":"Flokkimmunitet","b":"Så mange er immune at smitten ikke finner nye verter, slik at også uvaksinerte beskyttes.","u":"kapittel-5.html"},{"id":"t5-26","n":5,"c":"Kapittel 5","k":"Begrep","f":"Antibiotika","b":"Stoffer som hemmer eller dreper bakterier. Virker ikke mot virus.","u":"kapittel-5.html"},{"id":"t5-27","n":5,"c":"Kapittel 5","k":"Begrep","f":"Resistens","b":"Bakteriers evne til å overleve antibiotika.","u":"kapittel-5.html"},{"id":"t5-28","n":5,"c":"Kapittel 5","k":"Begrep","f":"Multiresistens","b":"Motstandsdyktighet mot flere typer antibiotika samtidig.","u":"kapittel-5.html"},{"id":"t5-29","n":5,"c":"Kapittel 5","k":"Begrep","f":"CRP","b":"C-reaktivt protein; stiger mye ved bakterieinfeksjon og brukes til å skille bakterie- fra virusinfeksjon.","u":"kapittel-5.html"},{"id":"t5-30","n":5,"c":"Kapittel 5","k":"Begrep","f":"Zoonose","b":"Sykdom som smitter mellom dyr og mennesker.","u":"kapittel-5.html"},{"id":"t5-31","n":5,"c":"Kapittel 5","k":"Begrep","f":"Prion","b":"Feilfoldet protein som kan gi sykdom, for eksempel kugalskap. Ikke levende.","u":"kapittel-5.html"},{"id":"r5-0","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva slags organismer kan gi infeksjoner?","b":"Bakterier, virus, sopp og parasitter, i tillegg til flercellede innvollsmarker.","u":"kapittel-5.html"},{"id":"r5-1","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Forklar ordene kolonisering, infeksjon og immunitet.","b":"Kolonisering: mikroorganismer har fast tilhold på kroppens overflater uten å gi sykdom. Infeksjon: mikroorganismer trenger inn i vevet, og vi kan bli syke. Immunitet: evnen til å motstå en infeksjon uten å bli syk.","u":"kapittel-5.html"},{"id":"r5-2","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva er et mikrobiom?","b":"Samlingen av alle mikroorganismer som lever på ytre og indre overflater hos en organisme. Noen er harmløse, noen nyttige og noen sykdomsframkallende.","u":"kapittel-5.html"},{"id":"r5-3","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Forklar forskjellen på epidemi og pandemi.","b":"En epidemi er et utbrudd i et avgrenset område eller en befolkning. En pandemi har spredd seg over store deler av verden, slik som svartedauden, spanskesyken og covid-19.","u":"kapittel-5.html"},{"id":"r5-4","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hvilke smittemåter har bakterier?","b":"Dråpesmitte og luftsmitte, direkte kontaktsmitte (også seksuelt overført), indirekte kontaktsmitte via gjenstander, og smitte gjennom vann og mat.","u":"kapittel-5.html"},{"id":"r5-5","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hvordan er et virus bygd opp?","b":"Arvestoff – enten DNA eller RNA – pakket inn i en kappe av proteiner, hos noen med en lipidmembran utenpå. Viruset har ingen organeller, ikke cytoplasma og ikke eget stoffskifte.","u":"kapittel-5.html"},{"id":"r5-6","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hvorfor regner vi ikke virus som levende?","b":"De kan bare formere seg inne i en vertscelle, har ikke eget stoffskifte og er ikke bygd opp av celler.","u":"kapittel-5.html"},{"id":"r5-7","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Forklar hvordan et virus formerer seg.","b":"Viruset fester seg til vertscellen og sender arvestoffet inn. Vertscellens maskineri brukes til å kopiere arvestoffet og lage virusproteiner. Nye viruspartikler settes sammen og frigjøres, ofte ved at cellen sprenges.","u":"kapittel-5.html"},{"id":"r5-8","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Gi eksempler på virus og virussykdommer hos mennesker.","b":"Influensavirus (influensa), koronavirus (covid-19), herpesvirus (munnsår), Epstein-Barr-virus (mononukleose), hiv (aids), varicella (vannkopper) og HPV (livmorhalskreft).","u":"kapittel-5.html"},{"id":"r5-9","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva er forskjellen på et DNA-virus og et RNA-virus?","b":"DNA-virus har DNA som arvestoff, for eksempel herpes. RNA-virus har RNA. Retrovirus som hiv lager en DNA-kopi med revers transkriptase og setter den inn i vertens DNA, mens influensa- og koronavirus kopierer RNA direkte i cytoplasmaet.","u":"kapittel-5.html"},{"id":"r5-10","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva er immunsystemets oppgaver?","b":"Å gjenkjenne mikroorganismer, fjerne dem som har trengt inn i vevet, og huske det første møtet slik at fjerningen går raskere neste gang.","u":"kapittel-5.html"},{"id":"r5-11","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hvilke av kroppens celler og vev deltar i immunforsvaret?","b":"Hvite blodceller, beinmargen, lymfesystemet og lymfevevet. I tillegg bidrar leveren med immunmolekyler, blodåreveggen ved betennelse og nervesystemet ved blant annet feberregulering.","u":"kapittel-5.html"},{"id":"r5-12","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Klarer immunforsvaret å skille fremmede celler fra dine egne?","b":"Ja. Det lærer seg å ikke reagere på kroppens egne molekyler, men bare på fremmede antigener. Svikter dette, får vi autoimmune sykdommer.","u":"kapittel-5.html"},{"id":"r5-13","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva består det medfødte ytre forsvaret av?","b":"Tørr, tett hud med talg, og slimhinner som skiller ut slim, magesyre og andre stoffer. I luftveiene frakter flimmerhår slimet mot svelget.","u":"kapittel-5.html"},{"id":"r5-14","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hvor i kroppen har vi slimhinner, og hvilken funksjon har de?","b":"I luftveiene, fordøyelseskanalen, de indre kjønnsorganene og urinveiene. Slimet fanger opp mikroorganismer og hindrer dem i å trenge inn i vevet, og inneholder stoffer som ødelegger cellemembraner.","u":"kapittel-5.html"},{"id":"r5-15","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva består det medfødte indre forsvaret av?","b":"Fagocytter (nøytrofile granulocytter, makrofager og dendrittiske celler), naturlige drepeceller, proteiner i blodet som skader eller merker mikroorganismer, og interferoner fra virusinfiserte celler.","u":"kapittel-5.html"},{"id":"r5-16","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Forklar begrepet fagocytose.","b":"Cellespising: fagocytten binder seg til molekyler på overflaten av mikroorganismen, omslutter den med cellemembranen og bryter den ned i lysosomer.","u":"kapittel-5.html"},{"id":"r5-17","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva er interferoner, og når skilles de ut?","b":"Proteiner som virusinfiserte celler skiller ut. De varsler nabocellene, som endrer seg slik at viruset hindres i å formere seg. Reaksjonen er ikke knyttet til ett bestemt virus.","u":"kapittel-5.html"},{"id":"r5-18","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Forklar hva som skjer når vi får en betennelse.","b":"Skadde celler skiller ut stoffer som utvider blodårene og åpner porene i kapillærene. Blodplasma lekker ut, og vi ser rødme, hevelse, varme og smerte. Fagocytter vandrer ut i vevet og spiser mikroorganismer, og dendrittiske celler frakter antigener til lymfeknutene.","u":"kapittel-5.html"},{"id":"r5-19","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Forklar hva vi mener med aktiv og passiv immunitet.","b":"Aktiv immunitet: kroppen lager selv antistoffer og hukommelsesceller etter vaksine eller sykdom, og beskyttelsen varer lenge. Passiv immunitet: ferdige antistoffer overføres fra et annet individ, virker straks, men varer bare to–tre måneder.","u":"kapittel-5.html"},{"id":"r5-20","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hvordan virker en vaksine?","b":"Vaksinen inneholder svekkede eller drepte mikroorganismer, eller bare antigener. Immunforsvaret reagerer som ved en infeksjon: fagocytter frakter antigenene til lymfeknutene, B- og T-celler aktiveres, og det dannes antistoffer og hukommelsesceller uten at du blir syk.","u":"kapittel-5.html"},{"id":"r5-21","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva er flokkimmunitet?","b":"Når så mange i befolkningen er immune at smitten ikke finner nok mottakelige verter. Da beskyttes også de som ikke kan vaksineres, som spedbarn og personer med svekket immunforsvar.","u":"kapittel-5.html"},{"id":"r5-22","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva er smalspektret og bredspektret antibiotika?","b":"Smalspektret virker mot få bakteriearter og skåner den nyttige floraen. Bredspektret virker mot mange arter og brukes når årsaken er ukjent, men øker faren for resistens.","u":"kapittel-5.html"},{"id":"r5-23","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva betyr det at bakterier blir resistente, og hva kan årsakene være?","b":"At de overlever antibiotikabehandling. Årsakene er mutasjoner og overføring av resistensgener i plasmider, kombinert med høyt forbruk i behandling og i dyrefôr, som gir seleksjon for de resistente bakteriene.","u":"kapittel-5.html"},{"id":"r5-24","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hva slags test kan avgjøre om infeksjonen skyldes bakterier eller virus?","b":"En CRP-test (hurtigsenkning) av en bloddråpe. Over 100 mg/l tyder på bakterieinfeksjon, under 50 mg/l på virusinfeksjon.","u":"kapittel-5.html"},{"id":"r5-25","n":5,"c":"Kapittel 5","k":"Repetisjon","f":"Hvorfor blir antibiotika i noen land gitt til husdyr?","b":"For å hindre sykdom i tette besetninger og fordi friske dyr utnytter fôret bedre og vokser raskere. Praksisen øker faren for resistente bakterier som kan spres til mennesker gjennom mat.","u":"kapittel-5.html"},{"id":"t6-0","n":6,"c":"Kapittel 6","k":"Begrep","f":"Stamcelle","b":"Uspesialisert celle som kan dele seg og gi opphav til både nye stamceller og spesialiserte celler.","u":"kapittel-6.html"},{"id":"t6-1","n":6,"c":"Kapittel 6","k":"Begrep","f":"Forløpercelle","b":"Celle mellom stamcelle og ferdig spesialisert celle.","u":"kapittel-6.html"},{"id":"t6-2","n":6,"c":"Kapittel 6","k":"Begrep","f":"Differensiering","b":"At en celle spesialiserer seg ved at gener aktiveres eller inaktiveres.","u":"kapittel-6.html"},{"id":"t6-3","n":6,"c":"Kapittel 6","k":"Begrep","f":"Epitelvev","b":"Overflatevev som dekker indre og ytre overflater.","u":"kapittel-6.html"},{"id":"t6-4","n":6,"c":"Kapittel 6","k":"Begrep","f":"Bindevev","b":"Vev som binder sammen, støtter og beskytter: brusk, bein, blod og fett.","u":"kapittel-6.html"},{"id":"t6-5","n":6,"c":"Kapittel 6","k":"Begrep","f":"Organ","b":"Samling av flere vevstyper som løser bestemte oppgaver.","u":"kapittel-6.html"},{"id":"t6-6","n":6,"c":"Kapittel 6","k":"Begrep","f":"Organsystem","b":"Gruppe organer som samarbeider om grunnleggende funksjoner.","u":"kapittel-6.html"},{"id":"t6-7","n":6,"c":"Kapittel 6","k":"Begrep","f":"Cellesyklus","b":"G1, S, G2, mitose og cytokinese – cellens vekst og deling.","u":"kapittel-6.html"},{"id":"t6-8","n":6,"c":"Kapittel 6","k":"Begrep","f":"Mitose","b":"Kjernedeling som gir to genetisk identiske datterceller.","u":"kapittel-6.html"},{"id":"t6-9","n":6,"c":"Kapittel 6","k":"Begrep","f":"Meiose","b":"To delinger som halverer kromosomtallet og gir fire haploide celler.","u":"kapittel-6.html"},{"id":"t6-10","n":6,"c":"Kapittel 6","k":"Begrep","f":"Kromatid","b":"Den ene av to identiske halvdeler av et kopiert kromosom.","u":"kapittel-6.html"},{"id":"t6-11","n":6,"c":"Kapittel 6","k":"Begrep","f":"Kreftceller","b":"Celler som deler seg for ofte eller dør for sjelden, som følge av mutasjoner.","u":"kapittel-6.html"},{"id":"t6-12","n":6,"c":"Kapittel 6","k":"Begrep","f":"Frøblad","b":"De første bladene på en plante; ligger ferdige i frøet.","u":"kapittel-6.html"},{"id":"t6-13","n":6,"c":"Kapittel 6","k":"Begrep","f":"Nakenfrøet","b":"Plante der frøemnet ikke er dekket av en fruktknute – bartrærne.","u":"kapittel-6.html"},{"id":"t6-14","n":6,"c":"Kapittel 6","k":"Begrep","f":"Dekkfrøet","b":"Plante med blomst der frøemnene ligger inni fruktknuten.","u":"kapittel-6.html"},{"id":"t6-15","n":6,"c":"Kapittel 6","k":"Begrep","f":"Rothår","b":"Utposninger fra rotas ytterhud som gir stor overflate for vannopptak.","u":"kapittel-6.html"},{"id":"t6-16","n":6,"c":"Kapittel 6","k":"Begrep","f":"Casparyske bånd","b":"Vannavstøtende bånd av suberin i innerhuden som styrer hva som slipper inn til ledningsvevet.","u":"kapittel-6.html"},{"id":"t6-17","n":6,"c":"Kapittel 6","k":"Begrep","f":"Vedrør","b":"Døde celler som frakter vann og ioner fra rot til topp.","u":"kapittel-6.html"},{"id":"t6-18","n":6,"c":"Kapittel 6","k":"Begrep","f":"Silrør","b":"Levende celler med følgeceller som frakter karbohydrater begge veier.","u":"kapittel-6.html"},{"id":"t6-19","n":6,"c":"Kapittel 6","k":"Begrep","f":"Transpirasjon","b":"Fordamping av vann fra planten, hovedsakelig gjennom spalteåpningene.","u":"kapittel-6.html"},{"id":"t6-20","n":6,"c":"Kapittel 6","k":"Begrep","f":"Kohesjon","b":"Kreftene som holder vannmolekylene sammen.","u":"kapittel-6.html"},{"id":"t6-21","n":6,"c":"Kapittel 6","k":"Begrep","f":"Adhesjon","b":"Kreftene som får vann til å klistre seg til veggene i vedrørene.","u":"kapittel-6.html"},{"id":"t6-22","n":6,"c":"Kapittel 6","k":"Begrep","f":"Rottrykk","b":"Overtrykk i vedrørene som oppstår når røttene tar opp vann ved osmose.","u":"kapittel-6.html"},{"id":"t6-23","n":6,"c":"Kapittel 6","k":"Begrep","f":"Kutikula","b":"Voksaktig, vanntett hinne på overflaten av blad og rot.","u":"kapittel-6.html"},{"id":"t6-24","n":6,"c":"Kapittel 6","k":"Begrep","f":"Spalteåpning (stoma)","b":"Åpning i bladets ytterhud, omgitt av to lukkeceller, som slipper gasser inn og ut.","u":"kapittel-6.html"},{"id":"t6-25","n":6,"c":"Kapittel 6","k":"Begrep","f":"Palisadeceller","b":"Langstrakte celler tett i tett på bladets overside der mye av fotosyntesen skjer.","u":"kapittel-6.html"},{"id":"t6-26","n":6,"c":"Kapittel 6","k":"Begrep","f":"Svampvev","b":"Celler med store luftrom på bladets underside, der CO₂ og O₂ sirkulerer.","u":"kapittel-6.html"},{"id":"t6-27","n":6,"c":"Kapittel 6","k":"Begrep","f":"Zygote","b":"Den befruktede eggcellen, diploid.","u":"kapittel-6.html"},{"id":"t6-28","n":6,"c":"Kapittel 6","k":"Begrep","f":"Blastocyst","b":"Hul celleklump med 100–200 celler som fester seg i livmorveggen.","u":"kapittel-6.html"},{"id":"t6-29","n":6,"c":"Kapittel 6","k":"Begrep","f":"Gastrulasjon","b":"Innfolding av blastocysten der de tre cellelagene dannes.","u":"kapittel-6.html"},{"id":"t6-30","n":6,"c":"Kapittel 6","k":"Begrep","f":"Yngelpleie","b":"Perioden der avkommet lever sammen med og passes av foreldrene.","u":"kapittel-6.html"},{"id":"r6-0","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Hvor i kroppen finnes stamceller?","b":"I alle vev og organer. De best kjente ligger i beinmargen og lager blodceller, men det finnes også nervestamceller, muskelstamceller, fettstamceller og stamceller i navlestreng og embryo.","u":"kapittel-6.html"},{"id":"r6-1","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Forklar delingen av en stamcelle.","b":"Når stamcellen deler seg, blir det dannet enten nye stamceller eller forløperceller. Forløpercellene deler seg videre mange ganger, og cellene differensieres til spesialiserte celletyper. Slik består stamcellebeholdningen selv om cellene deler seg.","u":"kapittel-6.html"},{"id":"r6-2","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Hva betyr det at en celle differensierer?","b":"At den spesialiserer seg til en bestemt celletype ved at noen gener slås på og andre av, slik at cellen lager bestemte proteiner. En muskelcelle og en fettcelle har samme DNA, men bruker ulike deler av det.","u":"kapittel-6.html"},{"id":"r6-3","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Gi noen eksempler på spesialiserte celler.","b":"Nerveceller, leverceller, røde og hvite blodceller, hudceller, muskelceller og kjønnsceller.","u":"kapittel-6.html"},{"id":"r6-4","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Forklar ordene vev, organ og organsystem.","b":"Vev er celler med samme oppgave som ligger samlet. Et organ er flere vevstyper som samarbeider om bestemte funksjoner, for eksempel hjertet. Et organsystem er flere organer som løser en større oppgave sammen, for eksempel fordøyelsessystemet.","u":"kapittel-6.html"},{"id":"r6-5","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Beskriv fasene i cellesyklusen.","b":"G1: cellen vokser og utfører sine oppgaver. S: DNA-et kopieres. G2: cellen vokser videre og forbereder delingen. Deretter mitose, der kjernen deles, og cytokinese, der cytoplasmaet deles i to celler.","u":"kapittel-6.html"},{"id":"r6-6","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Forklar forskjellene på kromatider og kromosomer.","b":"Et kromosom er et DNA-molekyl pakket rundt proteiner. Etter S-fasen består hvert kromosom av to identiske kromatider som henger sammen i sentromeren. Under delingen trekkes kromatidene fra hverandre og blir selvstendige kromosomer i hver sin dattercelle.","u":"kapittel-6.html"},{"id":"r6-7","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Hvorfor er regulering av celledeling viktig?","b":"Fordi kroppen må erstatte slitte celler og reparere skader i riktig tempo. Deler cellene seg for ofte eller dør for sjelden, oppstår kreft.","u":"kapittel-6.html"},{"id":"r6-8","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Forklar hva som skjer når et frø spirer.","b":"Frøet tar opp vann og sveller. Rota kommer først ut og forankrer planten og tar opp vann. Deretter foldes frøbladene ut, og planten begynner fotosyntese. Opplagsnæringen i frøet gir energi fram til plantene kan lage sin egen.","u":"kapittel-6.html"},{"id":"r6-9","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Hvor mange hovedgrupper av landplanter har vi, og hva er typisk for hver av dem?","b":"Tre: moser uten røtter og ledningsvev som formerer seg med sporer; karsporeplanter med røtter og ledningsvev som også formerer seg med sporer; og frøplanter med røtter, ledningsvev og frø.","u":"kapittel-6.html"},{"id":"r6-10","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Hvorfor kan bregner bli mye høyere enn moser?","b":"Bregner har ledningsvev som frakter vann og næring, og røtter som gir feste og stabil vanntilgang. Moser mangler begge deler og er derfor avhengige av å være små og tynne.","u":"kapittel-6.html"},{"id":"r6-11","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Forklar hvordan vann tas opp gjennom rota.","b":"Rothårene tar aktivt opp ioner, slik at konsentrasjonen inni blir høyere enn i jorda. Vann følger etter ved osmose. Vannet går enten gjennom cytoplasmaet i barkcellene eller mellom cellene, til det møter de casparyske båndene i innerhuden. Der må det gjennom cellene, som kontrollerer hva som slipper inn til vedrørene.","u":"kapittel-6.html"},{"id":"r6-12","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Beskriv hva som skjer i vedrør og silrør.","b":"Vedrørene frakter vann og ioner fra rot til topp gjennom døde celler med åpne endevegger. Silrørene frakter glukose og sukrose løst i vann, både opp og ned, gjennom levende celler med følgeceller.","u":"kapittel-6.html"},{"id":"r6-13","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Hvilke teorier forklarer at vann kommer helt opp i høye trær?","b":"Transpirasjons- og kohesjonsteorien. Fordamping fra bladene gir undertrykk som suger vannet opp, kohesjon holder vannsøylen samlet, adhesjon får vannet til å klistre seg til rørveggen, og rottrykket presser nedenfra.","u":"kapittel-6.html"},{"id":"r6-14","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Forklar funksjonen til spalteåpningene.","b":"De slipper CO₂ inn til fotosyntesen og O₂ og vanndamp ut. De åpnes når fotosyntesen i lukkecellene gir høyere konsentrasjon inni, slik at vann trekkes inn ved osmose og cellene buer utover. De lukkes når fotosyntesen avtar eller planten må spare vann.","u":"kapittel-6.html"},{"id":"r6-15","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Hva er et embryo, og hva er et foster?","b":"Embryo brukes om de tidligste stadiene – hos mennesket fram til utgangen av åttende svangerskapsuke. Deretter kalles det et foster.","u":"kapittel-6.html"},{"id":"r6-16","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Når begynner fosteret å produsere kjønnshormoner?","b":"Allerede seks–sju uker etter befruktningen. Hormonene bestemmer hvilket kjønn fosteret utvikler.","u":"kapittel-6.html"},{"id":"r6-17","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Hvilke hormoner påvirker pubertetsutviklingen?","b":"Hypotalamus påvirker hypofysen, som produserer FSH og LH. Disse setter i gang produksjonen av østrogen og progesteron i eggstokkene og testosteron i testiklene.","u":"kapittel-6.html"},{"id":"r6-18","n":6,"c":"Kapittel 6","k":"Repetisjon","f":"Hva regner vi som et menneskes reproduktive alder?","b":"Fra puberteten og omtrent 35–40 år framover for kvinner, fram til klimakteriet i 50–55-årsalderen. Menn produserer sædceller fra puberteten og livet ut, men mengden avtar med alderen.","u":"kapittel-6.html"},{"id":"t7-0","n":7,"c":"Kapittel 7","k":"Begrep","f":"Fordøyelse","b":"Mekanisk og enzymatisk nedbryting av store molekyler til molekyler som kan tas opp gjennom cellemembranen.","u":"kapittel-7.html"},{"id":"t7-1","n":7,"c":"Kapittel 7","k":"Begrep","f":"Intracellulær fordøyelse","b":"Nedbryting inne i cellen, for eksempel i en næringsvakuole hos amøber.","u":"kapittel-7.html"},{"id":"t7-2","n":7,"c":"Kapittel 7","k":"Begrep","f":"Ekstracellulær fordøyelse","b":"Nedbryting utenfor cellene, i en tarm eller i underlaget slik sopp gjør det.","u":"kapittel-7.html"},{"id":"t7-3","n":7,"c":"Kapittel 7","k":"Begrep","f":"Enzym","b":"Protein som katalyserer en bestemt kjemisk reaksjon, for eksempel spalting av stivelse.","u":"kapittel-7.html"},{"id":"t7-4","n":7,"c":"Kapittel 7","k":"Begrep","f":"Amylase","b":"Enzym som spalter stivelse til mindre sukkermolekyler.","u":"kapittel-7.html"},{"id":"t7-5","n":7,"c":"Kapittel 7","k":"Begrep","f":"Pepsin","b":"Enzym i magesekken som spalter proteiner; virker best ved lav pH.","u":"kapittel-7.html"},{"id":"t7-6","n":7,"c":"Kapittel 7","k":"Begrep","f":"Lipase","b":"Enzym som spalter fett til fettsyrer og glyserol.","u":"kapittel-7.html"},{"id":"t7-7","n":7,"c":"Kapittel 7","k":"Begrep","f":"Peristaltikk","b":"Bølgebevegelser i tarmveggen som driver maten framover.","u":"kapittel-7.html"},{"id":"t7-8","n":7,"c":"Kapittel 7","k":"Begrep","f":"Galle","b":"Væske fra leveren som emulgerer fett i små dråper.","u":"kapittel-7.html"},{"id":"t7-9","n":7,"c":"Kapittel 7","k":"Begrep","f":"Tarmtott","b":"Utposning i tynntarmen som gir stor overflate for næringsopptak.","u":"kapittel-7.html"},{"id":"t7-10","n":7,"c":"Kapittel 7","k":"Begrep","f":"Mikrovilli","b":"Mikroskopiske utposninger på tarmcellene som øker overflaten ytterligere.","u":"kapittel-7.html"},{"id":"t7-11","n":7,"c":"Kapittel 7","k":"Begrep","f":"Glykogen","b":"Lagringsform for glukose i lever og muskler.","u":"kapittel-7.html"},{"id":"t7-12","n":7,"c":"Kapittel 7","k":"Begrep","f":"Stivelse","b":"Plantenes lagringsform for glukose, for eksempel i potet og korn.","u":"kapittel-7.html"},{"id":"t7-13","n":7,"c":"Kapittel 7","k":"Begrep","f":"Mykorrhiza","b":"Mutualistisk samliv mellom sopphyfer og planterøtter.","u":"kapittel-7.html"},{"id":"t7-14","n":7,"c":"Kapittel 7","k":"Begrep","f":"Nitrogenfiksering","b":"Omdanning av N₂ fra lufta til nitrogenforbindelser organismen kan ta opp.","u":"kapittel-7.html"},{"id":"t7-15","n":7,"c":"Kapittel 7","k":"Begrep","f":"Kro","b":"Utvidelse av spiserøret hos fugler der maten bløtes opp.","u":"kapittel-7.html"},{"id":"t7-16","n":7,"c":"Kapittel 7","k":"Begrep","f":"Kråse","b":"Muskuløs mageavdeling hos fugler som maler maten, ofte ved hjelp av småstein.","u":"kapittel-7.html"},{"id":"t7-17","n":7,"c":"Kapittel 7","k":"Begrep","f":"Tarmflora","b":"Bakteriesamfunnet i tarmen; en del av mikrobiomet.","u":"kapittel-7.html"},{"id":"t7-18","n":7,"c":"Kapittel 7","k":"Begrep","f":"Prebiotisk mat","b":"Mat som gir næring til de nyttige bakteriene du allerede har.","u":"kapittel-7.html"},{"id":"t7-19","n":7,"c":"Kapittel 7","k":"Begrep","f":"Probiotisk mat","b":"Mat som tilfører levende, nyttige bakterier.","u":"kapittel-7.html"},{"id":"r7-0","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hva er fordøyelse?","b":"Mekanisk og enzymatisk nedbryting av store molekyler til molekyler som er små nok til å passere cellemembranen og bli tatt opp i cellene.","u":"kapittel-7.html"},{"id":"r7-1","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hvordan foregår fordøyelsen hos en amøbe?","b":"Amøben omslutter næringspartikkelen med cellemembranen ved endocytose og danner en næringsvakuole. Enzymer fra cytoplasmaet eller lysosomer bryter ned innholdet, næringen tas opp i cytosol, og avfallet skilles ut ved eksocytose.","u":"kapittel-7.html"},{"id":"r7-2","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hvorfor er sopper viktige nedbrytere?","b":"De skiller ut enzymer i underlaget og bryter ned dødt organisk materiale utenfor kroppen. Deretter tar de opp de små molekylene. Slik frigjøres næringsstoffene til kretsløpet igjen.","u":"kapittel-7.html"},{"id":"r7-3","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hvilken fordel gir en gjennomgående tarm?","b":"Maten går én vei, slik at tarmen kan deles i spesialiserte avsnitt med ulike enzymer og ulik pH. Dyret kan spise i perioder og fordøye etterpå, og fordøyelsen blir mer effektiv.","u":"kapittel-7.html"},{"id":"r7-4","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hvilke næringsstoffer må planter ta opp fra jorda?","b":"Mineralnæringsstoffer, blant annet nitrogen, fosfor, kalium, kalsium og magnesium, i tillegg til vann.","u":"kapittel-7.html"},{"id":"r7-5","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hva bruker planter vakuolen til?","b":"Til å opprettholde turgortrykket, lagre stoffer som fargestoffer og næring, og lagre avfallsstoffer og forsvarsstoffer som ville skadet cellen om de fløt fritt i cytosol.","u":"kapittel-7.html"},{"id":"r7-6","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hva skjer i magesekken?","b":"Slimhinnen skiller ut saltsyre med pH rundt 1,5 og enzymet pepsin. Proteinene begynner å spaltes, de fleste mikroorganismene drepes, og maten blandes med magesyren. Slim beskytter magesekkens egen vegg.","u":"kapittel-7.html"},{"id":"r7-7","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hvor tas det meste av næringen opp?","b":"I tynntarmen. Folder, tarmtotter og mikrovilli gir en enorm overflate, og glukose og aminosyrer tas opp aktivt til blodet, mens fett tas opp i lymfesystemet.","u":"kapittel-7.html"},{"id":"r7-8","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hvilke oppgaver har leveren?","b":"Lagrer glukose som glykogen, bygger om aminosyrer, lager galle og plasmaproteiner, og bryter ned legemidler, alkohol og andre giftstoffer.","u":"kapittel-7.html"},{"id":"r7-9","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hvorfor har planteetere lengre tarm enn kjøttetere?","b":"Cellulose i plantecelleveggene er tungt nedbrytbart og krever lang tid og hjelp fra mikroorganismer. Kjøtt er lett å fordøye, og kjøttetere klarer seg derfor med kort tarm.","u":"kapittel-7.html"},{"id":"r7-10","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hva er tarmfloraen, og hvorfor er den viktig?","b":"Bakteriesamfunnet i tarmen. Bakteriene hjelper til med å spalte maten, produserer blant annet K-vitamin, hindrer sykdomsframkallende bakterier i å få fotfeste, og påvirker immunforsvaret.","u":"kapittel-7.html"},{"id":"r7-11","n":7,"c":"Kapittel 7","k":"Repetisjon","f":"Hva er forskjellen på prebiotisk og probiotisk mat?","b":"Prebiotisk mat gir næring til bakteriene du allerede har, for eksempel løk, asparges og kikerter. Probiotisk mat tilfører levende bakterier, for eksempel yoghurt og surmelk.","u":"kapittel-7.html"},{"id":"t8-0","n":8,"c":"Kapittel 8","k":"Begrep","f":"Metabolisme","b":"Stoffskiftet: summen av oppbygging (anabolisme) og nedbryting (katabolisme).","u":"kapittel-8.html"},{"id":"t8-1","n":8,"c":"Kapittel 8","k":"Begrep","f":"Aerob celleånding","b":"Nedbryting av næringsstoffer med oksygen; gir 32 ATP per glukosemolekyl.","u":"kapittel-8.html"},{"id":"t8-2","n":8,"c":"Kapittel 8","k":"Begrep","f":"Anaerob celleånding","b":"Nedbryting uten oksygen, også kalt gjæring; gir 2 ATP per glukosemolekyl.","u":"kapittel-8.html"},{"id":"t8-3","n":8,"c":"Kapittel 8","k":"Begrep","f":"ATP","b":"Adenosintrifosfat, cellens viktigste energibærer.","u":"kapittel-8.html"},{"id":"t8-4","n":8,"c":"Kapittel 8","k":"Begrep","f":"Glykolysen","b":"Første trinn i celleåndingen, der glukose spaltes til pyrodruesyre i cytosol.","u":"kapittel-8.html"},{"id":"t8-5","n":8,"c":"Kapittel 8","k":"Begrep","f":"Krebssyklusen","b":"Andre trinn, der pyrodruesyre spaltes til karbondioksid.","u":"kapittel-8.html"},{"id":"t8-6","n":8,"c":"Kapittel 8","k":"Begrep","f":"Oksidativ fosforylering","b":"Tredje trinn, der energien i NADH og FADH₂ brukes til å danne ATP.","u":"kapittel-8.html"},{"id":"t8-7","n":8,"c":"Kapittel 8","k":"Begrep","f":"NADH","b":"Energibærer som dannes i glykolysen og krebssyklusen.","u":"kapittel-8.html"},{"id":"t8-8","n":8,"c":"Kapittel 8","k":"Begrep","f":"Fermentering","b":"Anaerob celleånding, for eksempel melkesyregjæring og alkoholgjæring.","u":"kapittel-8.html"},{"id":"t8-9","n":8,"c":"Kapittel 8","k":"Begrep","f":"Fakultativt anaerob","b":"Organisme som kan veksle mellom aerob og anaerob celleånding.","u":"kapittel-8.html"},{"id":"t8-10","n":8,"c":"Kapittel 8","k":"Begrep","f":"Obligat anaerob","b":"Organisme som dør i nærvær av oksygen.","u":"kapittel-8.html"},{"id":"t8-11","n":8,"c":"Kapittel 8","k":"Begrep","f":"Sukkulent","b":"Plante med eget vannlagrende vev, tilpasset tørre voksesteder.","u":"kapittel-8.html"},{"id":"t8-12","n":8,"c":"Kapittel 8","k":"Begrep","f":"Trakeer","b":"Forgreinede luftrør hos insekter som ender i luftsekker.","u":"kapittel-8.html"},{"id":"t8-13","n":8,"c":"Kapittel 8","k":"Begrep","f":"Gjeller","b":"Forgreinede utposninger dekket av ett cellelag, brukt til gassutveksling i vann.","u":"kapittel-8.html"},{"id":"t8-14","n":8,"c":"Kapittel 8","k":"Begrep","f":"Motstrømsprinsippet","b":"Blod og vann (eller varmt og kaldt blod) går motsatt vei, slik at utvekslingen blir maksimal.","u":"kapittel-8.html"},{"id":"t8-15","n":8,"c":"Kapittel 8","k":"Begrep","f":"Vekselvarm","b":"Dyr som endrer kroppstemperatur med omgivelsene.","u":"kapittel-8.html"},{"id":"t8-16","n":8,"c":"Kapittel 8","k":"Begrep","f":"Likevarm","b":"Dyr med konstant kroppstemperatur: fugler og pattedyr.","u":"kapittel-8.html"},{"id":"t8-17","n":8,"c":"Kapittel 8","k":"Begrep","f":"Åpent sirkulasjonssystem","b":"Blodet flyter fritt mellom cellene deler av veien.","u":"kapittel-8.html"},{"id":"t8-18","n":8,"c":"Kapittel 8","k":"Begrep","f":"Lukket sirkulasjonssystem","b":"Blodet går i blodårer hele veien rundt.","u":"kapittel-8.html"},{"id":"t8-19","n":8,"c":"Kapittel 8","k":"Begrep","f":"Hemoglobin","b":"Jernholdig, rødt blodpigment som binder oksygen.","u":"kapittel-8.html"},{"id":"t8-20","n":8,"c":"Kapittel 8","k":"Begrep","f":"Hemocyanin","b":"Kobberholdig blodpigment hos noen krepsdyr; blått når det binder oksygen.","u":"kapittel-8.html"},{"id":"t8-21","n":8,"c":"Kapittel 8","k":"Begrep","f":"Arterie","b":"Blodåre som fører blodet fra hjertet; tykk vegg med mye muskler.","u":"kapittel-8.html"},{"id":"t8-22","n":8,"c":"Kapittel 8","k":"Begrep","f":"Vene","b":"Blodåre som fører blodet til hjertet; tynn vegg og klaffer.","u":"kapittel-8.html"},{"id":"t8-23","n":8,"c":"Kapittel 8","k":"Begrep","f":"Kapillærår","b":"Den tynneste blodåren, der stoffer utveksles med cellene ved diffusjon.","u":"kapittel-8.html"},{"id":"t8-24","n":8,"c":"Kapittel 8","k":"Begrep","f":"Aorta","b":"Hovedpulsåren som går ut fra venstre hjertekammer.","u":"kapittel-8.html"},{"id":"t8-25","n":8,"c":"Kapittel 8","k":"Begrep","f":"Kransarterier","b":"Blodårene som forsyner selve hjertemuskelen.","u":"kapittel-8.html"},{"id":"t8-26","n":8,"c":"Kapittel 8","k":"Begrep","f":"Sinusknuten","b":"Samling spesialiserte celler i høyre forkammer som styrer hjerterytmen.","u":"kapittel-8.html"},{"id":"t8-27","n":8,"c":"Kapittel 8","k":"Begrep","f":"Koagulasjon","b":"Størkning av blodet når fibrinogen omdannes til fibrin.","u":"kapittel-8.html"},{"id":"r8-0","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hvilke to deler består metabolismen av?","b":"Anabolisme, der stoffer bygges opp, og katabolisme, der stoffer brytes ned.","u":"kapittel-8.html"},{"id":"r8-1","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Forklar med egne ord hva fotoautotrof, kjemoautotrof og heterotrof betyr.","b":"Fotoautotrofe organismer bruker sollys til å lage organiske forbindelser av uorganiske. Kjemoautotrofe bruker energi fra nedbryting av uorganiske forbindelser. Heterotrofe må ta opp ferdige organiske molekyler fra andre organismer.","u":"kapittel-8.html"},{"id":"r8-2","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hva er aerob celleånding?","b":"Nedbryting av næringsstoffer med oksygen, der energien lagres som ATP. Reaksjonen er glukose + oksygen → karbondioksid + vann + energi, og gir 32 ATP per glukosemolekyl.","u":"kapittel-8.html"},{"id":"r8-3","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hva er ATP, og hvordan dannes det?","b":"Adenosintrifosfat, cellens viktigste energibærer. Det dannes når ADP kobles til en fosfatgruppe, blant annet på den foldede indre mitokondriemembranen. Når ATP spaltes til ADP og fosfat, frigjøres energi til cellens arbeid.","u":"kapittel-8.html"},{"id":"r8-4","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hvilke tre deler består den aerobe celleåndingen av?","b":"Glykolysen, der glukose spaltes til pyrodruesyre; krebssyklusen, der pyrodruesyren spaltes til karbondioksid; og oksidativ fosforylering, der energien i NADH og FADH₂ brukes til å danne ATP.","u":"kapittel-8.html"},{"id":"r8-5","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hva er anaerob celleånding?","b":"Celleånding uten oksygen, også kalt fermentering eller gjæring. Den gir bare 2 ATP per glukosemolekyl.","u":"kapittel-8.html"},{"id":"r8-6","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Gi eksempler på organismer med anaerob celleånding.","b":"Melkesyrebakterier, eddiksyrebakterier, brødgjær, øl- og vingjær, og bakterier som *Clostridium difficile*, som er obligat anaerob.","u":"kapittel-8.html"},{"id":"r8-7","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hva dannes ved celleåndingen hos gjærceller og melkesyrebakterier?","b":"Gjærceller danner etanol, karbondioksid, ATP og vann. Melkesyrebakterier danner melkesyre, ATP og vann.","u":"kapittel-8.html"},{"id":"r8-8","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Har mennesker anaerob celleånding?","b":"Ja. Ved hard aktivitet får musklene for lite oksygen til å forbrenne aerobt, og de går over til melkesyregjæring. Melkesyren gir stølhet, men omdannes til pyrodruesyre igjen når blodet tilfører oksygen.","u":"kapittel-8.html"},{"id":"r8-9","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hva er gassutveksling?","b":"Opptak av oksygen og utskilling av karbondioksid.","u":"kapittel-8.html"},{"id":"r8-10","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hvordan foregår gassutvekslingen hos planter?","b":"Gjennom spalteåpningene, mest på undersiden av bladene. CO₂ tas opp til fotosyntesen og O₂ til celleåndingen, mens O₂, CO₂ og vanndamp slippes ut. Transporten er passiv, ved diffusjon.","u":"kapittel-8.html"},{"id":"r8-11","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hva bruker dyrene oksygenet til?","b":"Til aerob celleånding, der næringsstoffer brytes ned og energien lagres som ATP.","u":"kapittel-8.html"},{"id":"r8-12","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Gi eksempler på dyr uten gassutvekslingssystem, og forklar hvordan de tar opp oksygen.","b":"Nesledyr som maneter, flatmarker og enkle flercellede dyr, i tillegg til encellede protister. De tar opp oksygen ved diffusjon over hele overflaten, og har så få cellelag at avstanden blir kort.","u":"kapittel-8.html"},{"id":"r8-13","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Sammenlikn trakeer, gjeller og lunger.","b":"Trakeer er indre, forgreinede rør hos insekter som fører luft direkte til cellene, slik at blodet ikke trenger å frakte oksygen. Gjeller er ytre, forgreinede utposninger som bare fungerer i vann fordi de tørker ut i luft. Lunger er indre utposninger med fuktig overflate, beskyttet mot uttørking, og er mest forgreinet hos fugler og pattedyr.","u":"kapittel-8.html"},{"id":"r8-14","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Forklar motstrømsprinsippet.","b":"Blodet i kapillærårene går motsatt vei av vannstrømmen over gjellene. Dermed møter oksygenfattig blod hele veien vann med høyere oksygeninnhold, og opptil åtti prosent av oksygenet kan gå over i blodet. Gikk strømmene samme vei, ville utvekslingen stoppet når konsentrasjonene ble like.","u":"kapittel-8.html"},{"id":"r8-15","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Sammenlikn bygningen av lungene hos frosk og fugl.","b":"Frosken har to enkle, sekkeformede lunger uten forgreininger og tar mye oksygen gjennom huden. Fuglen har forgreinede lunger og i tillegg luftsekker, slik at ny og gammel luft ikke blandes. Det gjør fuglens oksygenopptak mye mer effektivt.","u":"kapittel-8.html"},{"id":"r8-16","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hva transporteres i sirkulasjonssystemet?","b":"Oksygen og karbondioksid, næringsstoffer, avfallsstoffer, hormoner, antistoffer og varme.","u":"kapittel-8.html"},{"id":"r8-17","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Forklar hva vi mener med åpent, lukket, enkelt og dobbelt sirkulasjonssystem.","b":"I et åpent system flyter blodet fritt mellom cellene deler av veien. I et lukket system går blodet i blodårer hele veien. Enkelt kretsløp: blodet passerer hjertet én gang per runde. Dobbelt: blodet passerer hjertet to ganger, i to atskilte kretsløp. Mennesket har et lukket, dobbelt system.","u":"kapittel-8.html"},{"id":"r8-18","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Beskriv bygning og funksjon hos arterier, kapillærårer og vener.","b":"Arterier har tykke, muskuløse og elastiske vegger og fører blodet fra hjertet under høyt trykk. Kapillærårene har vegger på ett cellelag, slik at stoffer kan diffundere ut og inn. Venene har tynnere vegger og klaffer som hindrer tilbakestrømming, og musklene rundt hjelper blodet tilbake til hjertet.","u":"kapittel-8.html"},{"id":"r8-19","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hvilke fordeler har et dyr med flere kammer i hjertet?","b":"Oksygenrikt og oksygenfattig blod holdes atskilt, slik at blodet ut i kroppen har høyt oksygeninnhold. Det gir høy forbrenning og gjør det mulig å være likevarm.","u":"kapittel-8.html"},{"id":"r8-20","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Hva består blodet av?","b":"Blodplasma med serum og fibrinogen, og tre typer blodceller: røde blodceller, hvite blodceller og blodplater.","u":"kapittel-8.html"},{"id":"r8-21","n":8,"c":"Kapittel 8","k":"Repetisjon","f":"Forklar begrepene aorta, hulvene, kransarterie og hjerteklaff.","b":"Aorta er hovedpulsåren fra venstre hjertekammer ut i kroppen. Hulvenene fører oksygenfattig blod fra kroppen til høyre forkammer. Kransarteriene forsyner selve hjertemuskelen med blod. Hjerteklaffene hindrer at blodet strømmer feil vei mellom kamrene og ut i arteriene.","u":"kapittel-8.html"},{"id":"t9-0","n":9,"c":"Kapittel 9","k":"Begrep","f":"Ekskresjon","b":"Utskilling av kroppens avfallsstoffer, særlig nitrogenholdig avfall.","u":"kapittel-9.html"},{"id":"t9-1","n":9,"c":"Kapittel 9","k":"Begrep","f":"Osmoregulering","b":"Regulering av vann- og saltinnholdet i kroppen.","u":"kapittel-9.html"},{"id":"t9-2","n":9,"c":"Kapittel 9","k":"Begrep","f":"Ammoniakk","b":"Svært giftig nitrogenholdig avfallsstoff som skilles ut av vannlevende dyr.","u":"kapittel-9.html"},{"id":"t9-3","n":9,"c":"Kapittel 9","k":"Begrep","f":"Urinsyre","b":"Tungt løselig avfallsstoff hos fugler, krypdyr og insekter; sparer vann.","u":"kapittel-9.html"},{"id":"t9-4","n":9,"c":"Kapittel 9","k":"Begrep","f":"Urinstoff (karbamid)","b":"Nitrogenholdig avfallsstoff hos pattedyr, skilles ut løst i urin.","u":"kapittel-9.html"},{"id":"t9-5","n":9,"c":"Kapittel 9","k":"Begrep","f":"Protonefridier","b":"Enkle utskillingsorganer hos flatmarker, med flammeceller.","u":"kapittel-9.html"},{"id":"t9-6","n":9,"c":"Kapittel 9","k":"Begrep","f":"Metanefridier","b":"Utskillingsorganer i hvert ledd hos leddmarker.","u":"kapittel-9.html"},{"id":"t9-7","n":9,"c":"Kapittel 9","k":"Begrep","f":"Malpighiske rør","b":"Rørformede utskillingsorganer hos insekter som tømmes i tarmen.","u":"kapittel-9.html"},{"id":"t9-8","n":9,"c":"Kapittel 9","k":"Begrep","f":"Nyrekapsel","b":"Bowmans kapsel; der blodvæske presses ut og forurinen dannes.","u":"kapittel-9.html"},{"id":"t9-9","n":9,"c":"Kapittel 9","k":"Begrep","f":"Forurin","b":"Væsken som presses ut i nyrekapselen, før reabsorpsjon.","u":"kapittel-9.html"},{"id":"t9-10","n":9,"c":"Kapittel 9","k":"Begrep","f":"Nyrekanal","b":"Rør der vann, salter og næringsstoffer tas opp igjen i blodet.","u":"kapittel-9.html"},{"id":"t9-11","n":9,"c":"Kapittel 9","k":"Begrep","f":"Henles sløyfe","b":"U-formet del av nyrekanalen der mye vann reabsorberes.","u":"kapittel-9.html"},{"id":"t9-12","n":9,"c":"Kapittel 9","k":"Begrep","f":"Reabsorpsjon","b":"Opptak av stoffer fra forurinen tilbake til blodet.","u":"kapittel-9.html"},{"id":"t9-13","n":9,"c":"Kapittel 9","k":"Begrep","f":"ADH","b":"Antidiuretisk hormon fra hypotalamus som øker vannopptaket i nyrene.","u":"kapittel-9.html"},{"id":"t9-14","n":9,"c":"Kapittel 9","k":"Begrep","f":"Tørstsenteret","b":"Området i storhjernebarken som registrerer behovet for vann.","u":"kapittel-9.html"},{"id":"r9-0","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Hvor lagrer plantene avfall, og hva slags avfall er det?","b":"I vakuolene. Det er biprodukter fra stoffskiftet, overskuddsstoffer og forsvarsstoffer som ville skadet cellen om de lå fritt i cytosol. Noe lagres også i blader, frukt og bark som felles, eller skilles ut fra røttene.","u":"kapittel-9.html"},{"id":"r9-1","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Hvordan kan lagringen i vakuolene være av verdi for oss?","b":"Mange av stoffene er nyttige eller velsmakende for oss: søt saft i frukt, syre i sitron, fargestoffer, koffein, nikotin og en rekke plantestoffer vi bruker i mat og medisin.","u":"kapittel-9.html"},{"id":"r9-2","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Forklar ordene ekskresjon og osmoregulering.","b":"Ekskresjon er utskilling av avfallsstoffer, særlig nitrogenholdige forbindelser fra nedbryting av proteiner. Osmoregulering er å holde vann- og saltkonsentrasjonen i kroppen mest mulig konstant.","u":"kapittel-9.html"},{"id":"r9-3","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Hva har osmoreguleringen å si for homeostasen?","b":"Den holder væskevolum, saltkonsentrasjon og dermed osmotisk trykk stabilt. Uten den ville cellene enten svelle opp eller skrumpe, og reaksjonene i cellene ville forstyrres.","u":"kapittel-9.html"},{"id":"r9-4","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Hvilke typer nitrogenholdig avfall skiller ulike dyr ut, og hvorfor er det forskjeller?","b":"Vannlevende dyr skiller ut ammoniakk, som er svært giftig, men fortynnes straks. Fugler, krypdyr og insekter skiller ut urinsyre, som er tungt løselig og sparer vann. Pattedyr skiller ut urinstoff, som er mindre giftig og kan skilles ut i moderate mengder vann.","u":"kapittel-9.html"},{"id":"r9-5","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Lag en oversikt over ekskresjonsorganene hos ulike dyr.","b":"Protister og enkle flercellede dyr: direkte over overflaten. Flatmarker: protonefridier med flammeceller. Leddmarker: metanefridier. Krepsdyr: avfallskjertler og gjeller. Insekter: malpighiske rør. Virveldyr: nyrer.","u":"kapittel-9.html"},{"id":"r9-6","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Er det noe system mellom type ekskresjonsorgan, dyrets størrelse og levested?","b":"Ja. Små dyr med kort avstand til overflaten klarer seg uten organer. Jo større dyret er, desto mer avansert er organet. Vannlevende dyr kan skille ut giftig ammoniakk og bruke mye vann, mens landlevende dyr må spare vann og skiller ut urinsyre eller urinstoff.","u":"kapittel-9.html"},{"id":"r9-7","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Hvorfor må blodet renses for nitrogenholdig avfall?","b":"Fordi ammoniakk og andre nitrogenforbindelser fra proteinnedbryting er giftige. Hoper de seg opp i blodet, skades cellene, og særlig hjernen er sårbar.","u":"kapittel-9.html"},{"id":"r9-8","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Hva er forurin?","b":"Væsken som presses ut av kapillærårene i nyrekapselen. Den inneholder vann, salter, glukose og aminosyrer, men normalt verken blodceller eller proteiner. Det dannes i underkant av to hundre liter forurin i døgnet.","u":"kapittel-9.html"},{"id":"r9-9","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Hva er en mekanoreseptor?","b":"En sansereseptor som reagerer på mekanisk påvirkning, som trykk, bevegelse eller strekk. I blodårene registrerer de blodtrykket og melder fra til den forlengede marg.","u":"kapittel-9.html"},{"id":"r9-10","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Hva er ADH?","b":"Antidiuretisk hormon, som produseres i hypotalamus og skilles ut fra hypofysen. Det øker antallet aktive akvaporiner i nyrekanaler og samlerør, slik at mer vann reabsorberes og urinen blir mer konsentrert.","u":"kapittel-9.html"},{"id":"r9-11","n":9,"c":"Kapittel 9","k":"Repetisjon","f":"Hvordan samarbeider hjernen og nyrene?","b":"Nerveceller i hypotalamus registrerer vannkonsentrasjonen i blodet, og tørstsenteret gir tørstefølelse. Hypotalamus produserer ADH som virker på målceller i nyrene, slik at vannopptaket justeres. Slik holdes væskebalansen stabil.","u":"kapittel-9.html"},{"id":"t10-0","n":10,"c":"Kapittel 10","k":"Begrep","f":"Stimulus","b":"Påvirkning som utløser en respons hos en organisme.","u":"kapittel-10.html"},{"id":"t10-1","n":10,"c":"Kapittel 10","k":"Begrep","f":"Tropisme","b":"Retningsbestemt vekst mot eller bort fra en påvirkning.","u":"kapittel-10.html"},{"id":"t10-2","n":10,"c":"Kapittel 10","k":"Begrep","f":"Fototropisme","b":"Vekst mot eller fra lyset.","u":"kapittel-10.html"},{"id":"t10-3","n":10,"c":"Kapittel 10","k":"Begrep","f":"Gravitropisme","b":"Vekst med eller mot tyngdekraften.","u":"kapittel-10.html"},{"id":"t10-4","n":10,"c":"Kapittel 10","k":"Begrep","f":"Nasti","b":"Bevegelse som ikke er retningsbestemt, for eksempel at blomster lukker seg i mørke.","u":"kapittel-10.html"},{"id":"t10-5","n":10,"c":"Kapittel 10","k":"Begrep","f":"Fotoperiodisme","b":"Plantens tilpasning til antall timer med lys og mørke i døgnet.","u":"kapittel-10.html"},{"id":"t10-6","n":10,"c":"Kapittel 10","k":"Begrep","f":"Auxin","b":"Plantehormon som fremmer lengdevekst og rotdannelse.","u":"kapittel-10.html"},{"id":"t10-7","n":10,"c":"Kapittel 10","k":"Begrep","f":"Cytokinin","b":"Plantehormon som fremmer celledeling og hindrer aldring.","u":"kapittel-10.html"},{"id":"t10-8","n":10,"c":"Kapittel 10","k":"Begrep","f":"Gibberellin","b":"Plantehormon som fremmer spiring og lengdevekst.","u":"kapittel-10.html"},{"id":"t10-9","n":10,"c":"Kapittel 10","k":"Begrep","f":"Etylen","b":"Gassformig plantehormon som fremmer fruktmodning og bladfelling.","u":"kapittel-10.html"},{"id":"t10-10","n":10,"c":"Kapittel 10","k":"Begrep","f":"Abscisinsyre","b":"Plantehormon som styrer frøhvile og lukker spalteåpningene ved tørke.","u":"kapittel-10.html"},{"id":"t10-11","n":10,"c":"Kapittel 10","k":"Begrep","f":"Hormon","b":"Signalmolekyl som produseres i en endokrin kjertel og fraktes med blodet til målceller.","u":"kapittel-10.html"},{"id":"t10-12","n":10,"c":"Kapittel 10","k":"Begrep","f":"Endokrin kjertel","b":"Kjertel som skiller ut hormoner direkte til blodet.","u":"kapittel-10.html"},{"id":"t10-13","n":10,"c":"Kapittel 10","k":"Begrep","f":"Målcelle","b":"Celle med reseptor som passer til et bestemt hormon.","u":"kapittel-10.html"},{"id":"t10-14","n":10,"c":"Kapittel 10","k":"Begrep","f":"Reseptor","b":"Protein som gjenkjenner og binder et bestemt signalmolekyl.","u":"kapittel-10.html"},{"id":"t10-15","n":10,"c":"Kapittel 10","k":"Begrep","f":"Tilbakekopling","b":"Reguleringsmekanisme der resultatet av en prosess virker tilbake på produksjonen.","u":"kapittel-10.html"},{"id":"t10-16","n":10,"c":"Kapittel 10","k":"Begrep","f":"Insulin","b":"Hormon fra bukspyttkjertelen som senker blodsukkeret ved å slippe glukose inn i cellene.","u":"kapittel-10.html"},{"id":"t10-17","n":10,"c":"Kapittel 10","k":"Begrep","f":"Glukagon","b":"Hormon fra bukspyttkjertelen som hever blodsukkeret ved å spalte glykogen.","u":"kapittel-10.html"},{"id":"t10-18","n":10,"c":"Kapittel 10","k":"Begrep","f":"Adrenalin","b":"Hormon fra binyrene som setter kroppen i beredskap; virker også som transmitter.","u":"kapittel-10.html"},{"id":"t10-19","n":10,"c":"Kapittel 10","k":"Begrep","f":"Melatonin","b":"Hormon fra epifysen som styrer døgnrytme og søvn.","u":"kapittel-10.html"},{"id":"t10-20","n":10,"c":"Kapittel 10","k":"Begrep","f":"Hormonhermer","b":"Kjemikalie som likner kroppens egne hormoner og kan forstyrre homeostasen.","u":"kapittel-10.html"},{"id":"t10-21","n":10,"c":"Kapittel 10","k":"Begrep","f":"Nervecelle","b":"Celle med dendritter, cellekropp, akson og aksonender som leder nerveimpulser.","u":"kapittel-10.html"},{"id":"t10-22","n":10,"c":"Kapittel 10","k":"Begrep","f":"Gliacelle","b":"Celle som isolerer aksonet med myelin, slik at impulsen går raskere.","u":"kapittel-10.html"},{"id":"t10-23","n":10,"c":"Kapittel 10","k":"Begrep","f":"Hvilepotensial","b":"Ladningsforskjellen på om lag −70 mV over membranen i en hvilende nervecelle.","u":"kapittel-10.html"},{"id":"t10-24","n":10,"c":"Kapittel 10","k":"Begrep","f":"Aksjonspotensial","b":"Kortvarig endring der innsiden blir positiv, og som forflytter seg langs nervecellen.","u":"kapittel-10.html"},{"id":"t10-25","n":10,"c":"Kapittel 10","k":"Begrep","f":"Natrium-kalium-pumpen","b":"Transportprotein som pumper tre Na⁺ ut og to K⁺ inn ved hjelp av ATP.","u":"kapittel-10.html"},{"id":"t10-26","n":10,"c":"Kapittel 10","k":"Begrep","f":"Terskelverdi","b":"Ladningsforskjellen på −55 mV som må nås for at et aksjonspotensial skal utløses.","u":"kapittel-10.html"},{"id":"t10-27","n":10,"c":"Kapittel 10","k":"Begrep","f":"Synapse","b":"Kløften mellom to nerveceller eller mellom nervecelle og målcelle.","u":"kapittel-10.html"},{"id":"t10-28","n":10,"c":"Kapittel 10","k":"Begrep","f":"Transmitter","b":"Signalmolekyl som overfører nerveimpulsen i synapsen.","u":"kapittel-10.html"},{"id":"t10-29","n":10,"c":"Kapittel 10","k":"Begrep","f":"Adaptasjon","b":"Tilvenning: vi slutter å registrere gjentatte, uviktige stimuli.","u":"kapittel-10.html"},{"id":"t10-30","n":10,"c":"Kapittel 10","k":"Begrep","f":"Refleksbue","b":"Rask nervebane fra sansecelle via ryggmargen til muskel, uten om hjernen.","u":"kapittel-10.html"},{"id":"t10-31","n":10,"c":"Kapittel 10","k":"Begrep","f":"Autonomt nervesystem","b":"Den delen av det motoriske nervesystemet som ikke er viljestyrt.","u":"kapittel-10.html"},{"id":"t10-32","n":10,"c":"Kapittel 10","k":"Begrep","f":"Sympatisk nervesystem","b":"Setter kroppen i beredskap – kamp eller flukt.","u":"kapittel-10.html"},{"id":"t10-33","n":10,"c":"Kapittel 10","k":"Begrep","f":"Parasympatisk nervesystem","b":"Gir hvile og fordøyelse.","u":"kapittel-10.html"},{"id":"r10-0","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvorfor må organismer kunne reagere på stimuli?","b":"For å finne mat og ly, unngå fiender, vokse mot lyset og tilpasse seg endringer i omgivelsene. Uten respons på stimuli ville individet ikke overlevd lenge nok til å formere seg.","u":"kapittel-10.html"},{"id":"r10-1","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Forklar fotoperiodisme.","b":"Plantens tilpasning til antall timer med lys og mørke i døgnet. Langdagsplanter blomstrer når dagene blir lange nok, kortdagsplanter når de blir korte nok. Daglengden styrer også vekststopp, bladfelling og knoppdannelse.","u":"kapittel-10.html"},{"id":"r10-2","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvorfor må plantestengelen både være bøyelig og stiv?","b":"Stiv nok til å holde planten oppreist og strekke bladene mot lyset, bøyelig nok til å gi etter for vind uten å knekke. Trær som vokser på vindutsatte steder, får kortere og tykkere stamme og vokser ofte i spiralform.","u":"kapittel-10.html"},{"id":"r10-3","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvilken fordel har planter av å registrere feromoner fra insekter?","b":"De rekker å produsere forsvarsstoffer før angrepet starter, slik at larvene møter en plante som smaker vondt eller er vanskelig å fordøye.","u":"kapittel-10.html"},{"id":"r10-4","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvilke reaksjoner fremmes av de fem plantehormonene?","b":"Auxin: lengdevekst, rotdannelse og fruktutvikling. Cytokinin: celledeling og vekst, hindrer aldring. Gibberellin: spiring, lengdevekst og celledeling. Etylen: modning av frukt, blomstring og bladfelling. Abscisinsyre: frødannelse, frøhvile og lukking av spalteåpninger ved tørke.","u":"kapittel-10.html"},{"id":"r10-5","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvilke to kommunikasjonssystemer har et flercellet dyr, og hvorfor trengs begge?","b":"Hormonsystemet og nervesystemet. Nervesystemet gir raske, presise signaler til bestemte muskler og kjertler. Hormonsystemet er langsommere, men når mange celler samtidig og gir langvarige virkninger som vekst, stoffskifte og formering.","u":"kapittel-10.html"},{"id":"r10-6","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hva mener vi med målcelle og reseptor?","b":"En målcelle er en celle som reagerer på et bestemt hormon. Reseptoren er et protein på eller i målcellen som gjenkjenner og binder hormonet og utløser reaksjonen inne i cellen.","u":"kapittel-10.html"},{"id":"r10-7","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hva er en endokrin kjertel?","b":"En kjertel som skiller ut hormoner direkte til blodet, for eksempel hypofysen, skjoldbruskkjertelen, binyrene, bukspyttkjertelen, eggstokkene og testiklene.","u":"kapittel-10.html"},{"id":"r10-8","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvordan fungerer tilbakekoplingsmekanismene i hormonsystemet?","b":"Resultatet av hormonets virkning virker tilbake på kjertelen. Stiger blodsukkeret, skilles det ut insulin som senker det igjen; synker det, skilles det ut glukagon. Slik holdes nivået innenfor snevre grenser.","u":"kapittel-10.html"},{"id":"r10-9","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvorfor må vi ha et tilnærmet konstant nivå av glukose i blodet?","b":"Hjernen bruker bare glukose som energikilde og har ingen egne lagre. For lavt blodsukker kan gi hjerneskade, mens for høyt over tid skader blodårer og nerver.","u":"kapittel-10.html"},{"id":"r10-10","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Forklar hvordan to celletyper i bukspyttkjertelen samarbeider om blodsukkeret.","b":"β-cellene produserer insulin når blodsukkeret er høyt, slik at glukose lagres som glykogen i lever og muskler. α-cellene produserer glukagon når blodsukkeret er lavt, slik at glykogen spaltes til glukose. Nervesystemet registrerer nivået og styrer hvilke celler som aktiveres.","u":"kapittel-10.html"},{"id":"r10-11","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvilke fire funksjoner har en nervecelle?","b":"Å motta informasjon fra omgivelsene eller andre nerveceller, å tolke den og eventuelt lage en nerveimpuls, å lede impulsen fra den ene enden av cellen til den andre, og å overføre den til en annen nervecelle eller en målcelle.","u":"kapittel-10.html"},{"id":"r10-12","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvilke tre typer nerveceller har vi?","b":"Sensoriske nerveceller (sanseceller), internevroner (forbindelsesceller) og motoriske nerveceller.","u":"kapittel-10.html"},{"id":"r10-13","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hva er natrium-kalium-pumpen?","b":"Et transportprotein som ved hjelp av ATP pumper tre Na⁺-ioner ut og to K⁺-ioner inn. Dermed blir utsiden mer positiv enn innsiden, og hvilepotensialet på −70 mV opprettholdes.","u":"kapittel-10.html"},{"id":"r10-14","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Forklar ordene membranpotensial, hvilepotensial og aksjonspotensial.","b":"Membranpotensial er ladningsforskjellen mellom innsiden og utsiden av cellemembranen. Hvilepotensialet er membranpotensialet i en hvilende nervecelle, om lag −70 mV. Aksjonspotensialet er den kortvarige tilstanden der innsiden blir positiv fordi Na⁺ strømmer inn, og det er denne endringen som forflytter seg som en nerveimpuls.","u":"kapittel-10.html"},{"id":"r10-15","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Forklar impulsoverføringen i synapsen.","b":"Aksjonspotensialet når aksonenden og får blærer med transmittere til å tømme innholdet ut i synapsekløften ved eksocytose. Transmitterne binder seg til reseptorer på neste celle, natriumporter åpnes, og et nytt aksjonspotensial utløses. Deretter brytes transmitteren ned eller tas opp igjen.","u":"kapittel-10.html"},{"id":"r10-16","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hva er cannabis, og hvordan påvirker det kroppen?","b":"Marihuana er tørkede blader og hasj plantevæske fra cannabisplanten. Virkestoffet binder seg til reseptorer som skal gi smertelindring og metthetsfølelse, og gir rus, økt sultfølelse og redusert smerte. Samtidig forstyrres kroppens egen regulering.","u":"kapittel-10.html"},{"id":"r10-17","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hva er SNS og PNS?","b":"Sentralnervesystemet, som består av hjernen og ryggmargen, og det perifere nervesystemet, som er nervecellene til og fra sentralnervesystemet.","u":"kapittel-10.html"},{"id":"r10-18","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvilken funksjon har hjernehinnene og cerebrospinalvæsken?","b":"Tre hjernehinner dekker hjernen og ryggmargen. Mellom de to innerste ligger cerebrospinalvæske som demper støt og beskytter mot skade.","u":"kapittel-10.html"},{"id":"r10-19","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvilken betydning har hjernebjelken?","b":"Den binder sammen venstre og høyre hjernehalvdel med bunter av aksoner, slik at hemisfærene kan utveksle informasjon.","u":"kapittel-10.html"},{"id":"r10-20","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hva er en refleks?","b":"En rask, automatisk respons der impulsen går fra en sensorisk nervecelle, eventuelt via et internevron i ryggmargen, direkte til en motorisk nervecelle – uten å gå om hjernen først.","u":"kapittel-10.html"},{"id":"r10-21","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Forklar hvordan det perifere nervesystemet er delt inn.","b":"I et sensorisk system, som leder signaler fra sansene inn til sentralnervesystemet, og et motorisk system. Det motoriske deles i det somatiske (viljestyrte) og det autonome (ikke viljestyrte), og det autonome deles igjen i det sympatiske og det parasympatiske.","u":"kapittel-10.html"},{"id":"r10-22","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hva er hypofysen og hypotalamus?","b":"Hypotalamus er en del av mellomhjernen og det overordnede senteret for hormonsystemet; den har både nerveceller og hormonproduserende celler. Hypofysen er en liten kjertel like under, på størrelse med en ert, som produserer og lagrer flere av kroppens viktigste hormoner. Sammen kopler de nervesystemet og hormonsystemet.","u":"kapittel-10.html"},{"id":"r10-23","n":10,"c":"Kapittel 10","k":"Repetisjon","f":"Hvilke sanser har du, og hvilke sansereseptorer finnes?","b":"Syn, hørsel, lukt, smak og berøring. Reseptortypene er mekanoreseptorer, kjemoreseptorer, termoreseptorer, fotoreseptorer og smertereseptorer.","u":"kapittel-10.html"},{"id":"t11-0","n":11,"c":"Kapittel 11","k":"Begrep","f":"Tropisme","b":"Retningsbestemt vekst mot eller bort fra en påvirkning.","u":"kapittel-11.html"},{"id":"t11-1","n":11,"c":"Kapittel 11","k":"Begrep","f":"Nasti","b":"Bevegelse hos planter som ikke er retningsbestemt.","u":"kapittel-11.html"},{"id":"t11-2","n":11,"c":"Kapittel 11","k":"Begrep","f":"Strekningsvekst","b":"Vekst der cellene blir lengre, ofte på den ene siden av stengelen.","u":"kapittel-11.html"},{"id":"t11-3","n":11,"c":"Kapittel 11","k":"Begrep","f":"Ytre skjelett","b":"Hardt skall utenpå kroppen, som hos insekter og krepsdyr.","u":"kapittel-11.html"},{"id":"t11-4","n":11,"c":"Kapittel 11","k":"Begrep","f":"Indre skjelett","b":"Skjelett inne i kroppen, som hos virveldyr.","u":"kapittel-11.html"},{"id":"t11-5","n":11,"c":"Kapittel 11","k":"Begrep","f":"Sene","b":"Sterkt bindevev som fester muskel til knokkel.","u":"kapittel-11.html"},{"id":"t11-6","n":11,"c":"Kapittel 11","k":"Begrep","f":"Ledd","b":"Bevegelig forbindelse mellom to knokler, med brusk på endene.","u":"kapittel-11.html"},{"id":"t11-7","n":11,"c":"Kapittel 11","k":"Begrep","f":"Brusk","b":"Glatt, slitesterkt bindevev som dekker leddflatene.","u":"kapittel-11.html"},{"id":"t11-8","n":11,"c":"Kapittel 11","k":"Begrep","f":"Beinmarg","b":"Vevet inne i knoklene der blodcellene dannes.","u":"kapittel-11.html"},{"id":"t11-9","n":11,"c":"Kapittel 11","k":"Begrep","f":"Vekstskive","b":"Bruskområde i knokkelenden som gir lengdevekst.","u":"kapittel-11.html"},{"id":"t11-10","n":11,"c":"Kapittel 11","k":"Begrep","f":"Aktin","b":"Proteinfiber i muskelceller.","u":"kapittel-11.html"},{"id":"t11-11","n":11,"c":"Kapittel 11","k":"Begrep","f":"Myosin","b":"Proteinfiber som drar aktinet mot seg og gjør muskelen kortere.","u":"kapittel-11.html"},{"id":"t11-12","n":11,"c":"Kapittel 11","k":"Begrep","f":"Myoglobin","b":"Rødt protein i muskelceller som lagrer oksygen.","u":"kapittel-11.html"},{"id":"t11-13","n":11,"c":"Kapittel 11","k":"Begrep","f":"Tverrstripet muskulatur","b":"Skjelettmuskulatur med regelmessig mønster av aktin og myosin; viljestyrt.","u":"kapittel-11.html"},{"id":"t11-14","n":11,"c":"Kapittel 11","k":"Begrep","f":"Glatt muskulatur","b":"Muskulatur i indre organer; ikke viljestyrt.","u":"kapittel-11.html"},{"id":"t11-15","n":11,"c":"Kapittel 11","k":"Begrep","f":"Hjertemuskulatur","b":"Tverrstripet, men ikke viljestyrt muskulatur som bare finnes i hjertet.","u":"kapittel-11.html"},{"id":"r11-0","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Hva slags to typer bevegelse finner vi hos planter?","b":"Tropismer, som er retningsbestemt vekst styrt av plantehormoner, og nastier, som er bevegelser uten retning, styrt av trykk- og ioneendringer i cellene.","u":"kapittel-11.html"},{"id":"r11-1","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Nevn eksempler på at planters vekst tilpasser seg lys.","b":"Blader og blomster vender seg mot lyset, slyngplanter vokser mot lyse åpninger, og planter i mørke strekker seg lange og bleke. Løvetann og snøsøte åpner blomsten i sol og lukker den i mørke.","u":"kapittel-11.html"},{"id":"r11-2","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Hva er fototropisme og gravitropisme?","b":"Fototropisme er retningsbestemt vekst mot eller fra lyset. Gravitropisme er vekst med eller mot tyngdekraften: rota vokser nedover, skuddet oppover.","u":"kapittel-11.html"},{"id":"r11-3","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Forklar forskjellen på fototropisme og fotonasti.","b":"Begge utløses av lys, men fototropisme er retningsbestemt vekst – planten vokser mot lyskilden. Fotonasti er en bevegelse uten retning, som at blomsten åpner og lukker seg, og den skyldes trykkendringer, ikke vekst.","u":"kapittel-11.html"},{"id":"r11-4","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Hvilke deler består bevegelsessystemet av?","b":"Skjelettet, senene og musklene som er festet til skjelettet med sener.","u":"kapittel-11.html"},{"id":"r11-5","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Forklar forskjellen på ytre og indre skjelett.","b":"Ytre skjelett er et hardt skall utenpå kroppen, som hos insekter og krepsdyr; det beskytter godt og hindrer uttørking, men må skiftes ved vekst. Indre skjelett ligger inne i kroppen og vokser sammen med dyret.","u":"kapittel-11.html"},{"id":"r11-6","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Forklar hvordan muskler og skjelett samarbeider.","b":"Musklene er festet til knoklene med sener på hver side av et ledd. Når muskelcellene trekker seg sammen, blir muskelen kortere og trekker knokkelen med seg. Fordi muskler bare kan trekke aktivt, må en bøyemuskel og en strekkemuskel samarbeide om bevegelsen.","u":"kapittel-11.html"},{"id":"r11-7","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Hvor finnes den røde beinmargen?","b":"I hulrommene inne i de største knoklene, særlig i lårbein og hofte. Der ligger stamcellene som produserer blodceller.","u":"kapittel-11.html"},{"id":"r11-8","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Forklar likheter og forskjeller på langsomme og raske muskelfibre.","b":"Begge er tverrstripete skjelettmuskelceller med aktin og myosin. Langsomme (røde) celler har mye myoglobin og mange mitokondrier, er utholdende og forbrenner aerobt. Raske (hvite) celler har lite myoglobin, er sterkere, men blir fort trøtte og bruker mer anaerob forbrenning.","u":"kapittel-11.html"},{"id":"r11-9","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Hva er forskjellen på rødt og hvitt kjøtt?","b":"Rødt kjøtt, som fra okse og sau, har mest røde, utholdende muskelceller med mye myoglobin. Hvitt kjøtt, som fra kylling og kalkun, har mest hvite, raske muskelceller med lite myoglobin.","u":"kapittel-11.html"},{"id":"r11-10","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Hvordan samvirker myosin og aktin?","b":"Myosinhodene fester seg til aktinfibrene og vrir seg, slik at fibrene dras mot hverandre og muskelcellen blir kortere. Deretter slipper myosinet taket og fester seg lenger framme. Hvert steg krever ATP.","u":"kapittel-11.html"},{"id":"r11-11","n":11,"c":"Kapittel 11","k":"Repetisjon","f":"Hvorfor må muskelceller ha svært mange mitokondrier?","b":"Fordi hver sammentrekning krever ATP. Ved langvarig arbeid må cellen produsere ATP kontinuerlig ved aerob celleånding, og det krever stor samlet indre membranoverflate.","u":"kapittel-11.html"},{"id":"t12-0","n":12,"c":"Kapittel 12","k":"Begrep","f":"Todeling","b":"Ukjønnet formering der cellen kopierer DNA-et og deler seg i to.","u":"kapittel-12.html"},{"id":"t12-1","n":12,"c":"Kapittel 12","k":"Begrep","f":"Konjugasjon","b":"Overføring av DNA mellom to bakterier gjennom en tråd.","u":"kapittel-12.html"},{"id":"t12-2","n":12,"c":"Kapittel 12","k":"Begrep","f":"Transformasjon","b":"At en bakterie tar opp fritt DNA fra omgivelsene.","u":"kapittel-12.html"},{"id":"t12-3","n":12,"c":"Kapittel 12","k":"Begrep","f":"Transduksjon","b":"Overføring av bakteriegener med en bakteriofag.","u":"kapittel-12.html"},{"id":"t12-4","n":12,"c":"Kapittel 12","k":"Begrep","f":"Generasjonsveksling","b":"Veksling mellom en kjønnet og en ukjønnet generasjon.","u":"kapittel-12.html"},{"id":"t12-5","n":12,"c":"Kapittel 12","k":"Begrep","f":"Gametofytt","b":"Kjønnsplanten som lager kjønnsceller; haploid.","u":"kapittel-12.html"},{"id":"t12-6","n":12,"c":"Kapittel 12","k":"Begrep","f":"Sporofytt","b":"Sporeplanten som lager sporer; diploid.","u":"kapittel-12.html"},{"id":"t12-7","n":12,"c":"Kapittel 12","k":"Begrep","f":"Pollen","b":"Plantenes hannlige kjønnsceller, som gjør befruktning mulig uten vann.","u":"kapittel-12.html"},{"id":"t12-8","n":12,"c":"Kapittel 12","k":"Begrep","f":"Dobbel befruktning","b":"Hos dekkfrøede planter: én kjønnscelle befrukter eggcellen, en annen danner opplagsnæring.","u":"kapittel-12.html"},{"id":"t12-9","n":12,"c":"Kapittel 12","k":"Begrep","f":"Pollinering","b":"Overføring av pollen til arret eller frøemnet.","u":"kapittel-12.html"},{"id":"t12-10","n":12,"c":"Kapittel 12","k":"Begrep","f":"Vegetativ formering","b":"Ukjønnet formering hos planter, for eksempel med utløpere eller yngleknopper.","u":"kapittel-12.html"},{"id":"t12-11","n":12,"c":"Kapittel 12","k":"Begrep","f":"Knoppskyting","b":"Ukjønnet formering der en liten utgave vokser ut fra morindividet.","u":"kapittel-12.html"},{"id":"t12-12","n":12,"c":"Kapittel 12","k":"Begrep","f":"Fragmentering","b":"Ukjønnet formering der kroppen deles og hver del blir et nytt individ.","u":"kapittel-12.html"},{"id":"t12-13","n":12,"c":"Kapittel 12","k":"Begrep","f":"Partenogenese","b":"Jomfrufødsel: egg utvikler seg til nye individer uten befruktning.","u":"kapittel-12.html"},{"id":"t12-14","n":12,"c":"Kapittel 12","k":"Begrep","f":"Hermafroditt","b":"Tokjønnet individ som lager både egg- og sædceller.","u":"kapittel-12.html"},{"id":"t12-15","n":12,"c":"Kapittel 12","k":"Begrep","f":"Kryssbefruktning","b":"To tokjønnede individer befrukter hverandre.","u":"kapittel-12.html"},{"id":"t12-16","n":12,"c":"Kapittel 12","k":"Begrep","f":"Ytre befruktning","b":"Kjønnscellene smelter sammen utenfor kroppen, i vann.","u":"kapittel-12.html"},{"id":"t12-17","n":12,"c":"Kapittel 12","k":"Begrep","f":"Indre befruktning","b":"Befruktningen skjer inne i hunnens kropp.","u":"kapittel-12.html"},{"id":"t12-18","n":12,"c":"Kapittel 12","k":"Begrep","f":"Feromon","b":"Duftstoff som brukes til kommunikasjon mellom individer.","u":"kapittel-12.html"},{"id":"t12-19","n":12,"c":"Kapittel 12","k":"Begrep","f":"Zygote","b":"Den befruktede eggcellen, diploid.","u":"kapittel-12.html"},{"id":"r12-0","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Kan bakterier formere seg kjønnet?","b":"Nei. De formerer seg bare ukjønnet ved todeling. Genetisk variasjon får de gjennom mutasjoner og gjennom overføring av DNA ved konjugasjon, transformasjon og transduksjon.","u":"kapittel-12.html"},{"id":"r12-1","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hva er en bakteriofag?","b":"Et virus som angriper bakterier. Ved transduksjon kan den ta med seg bakteriegener fra én bakterie til en annen.","u":"kapittel-12.html"},{"id":"r12-2","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hvordan utveksler bakterier arvestoff?","b":"Ved konjugasjon, der den ene lager en tråd til den andre og overfører DNA eller plasmider; ved transformasjon, der fritt DNA tas opp fra omgivelsene; og ved transduksjon med bakteriofager.","u":"kapittel-12.html"},{"id":"r12-3","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hvilken fordel har det for en bakterie å få arvestoff fra andre?","b":"Den kan få nye egenskaper med en gang, for eksempel antibiotikaresistens eller evnen til å bruke en ny næringskilde. Det gir raskere tilpasning enn å vente på mutasjoner.","u":"kapittel-12.html"},{"id":"r12-4","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Forklar forskjellen mellom kjønnet og ukjønnet formering.","b":"Ved ukjønnet formering lager ett individ nye individer uten at kjønnsceller smelter sammen, og avkommet blir kloner. Ved kjønnet formering smelter to haploide kjønnsceller sammen til en diploid zygote, og avkommet får arv fra begge foreldrene.","u":"kapittel-12.html"},{"id":"r12-5","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hvordan definerer vi generasjonsveksling hos planter?","b":"Veksling mellom en gametofyttgenerasjon som lager kjønnsceller, og en sporofyttgenerasjon som lager sporer.","u":"kapittel-12.html"},{"id":"r12-6","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hva kjennetegner sporeplanten og kjønnsplanten?","b":"Sporeplanten (sporofytten) er diploid og danner sporer ved meiose. Kjønnsplanten (gametofytten) er haploid og danner kjønnsceller ved mitose. Hos moser dominerer gametofytten, hos bregner og frøplanter sporofytten.","u":"kapittel-12.html"},{"id":"r12-7","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Forklar formeringen hos moser.","b":"Den grønne mosen er gametofytten. På toppen dannes hannlige og hunnlige kjønnsceller. En vanndråpe frakter den hannlige cellen til en nabostilk, og zygoten som dannes, vokser opp til en brun stilk med sporehus – sporofytten. Derfra drysser haploide sporer som vokser opp til nye grønne moser.","u":"kapittel-12.html"},{"id":"r12-8","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hva er et sporehus og en spore?","b":"Sporehuset er strukturen der sporene dannes ved meiose. En spore er en haploid celle som kan spire til en ny plante uten å bli befruktet.","u":"kapittel-12.html"},{"id":"r12-9","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hvorfor kaller vi noen planter frøplanter?","b":"Fordi de formerer seg med frø – et plantefoster med opplagsnæring inne i et beskyttende skall. Frøet tåler tørke, kan lagres lenge og spires først når forholdene er gunstige.","u":"kapittel-12.html"},{"id":"r12-10","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hva er et fruktemne, en fruktknute og et frø?","b":"Fruktemnet er den hunnlige delen av blomsten og består av fruktknute, griffel og arr. Fruktknuten er den nederste, utvidede delen der frøemnene ligger. Frøet er det befruktede og modnede frøemnet, med plantefoster og opplagsnæring.","u":"kapittel-12.html"},{"id":"r12-11","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Forklar hvorfor noen planter er nakenfrøede og andre dekkfrøede.","b":"Hos nakenfrøede lander pollenet i en åpning rett utenfor frøemnet, og frøet ligger åpent på kongleskjellet. Hos dekkfrøede lander pollenet på arret og må vokse ned gjennom griffelen; frøemnene ligger beskyttet inne i fruktknuten, som blir til en frukt.","u":"kapittel-12.html"},{"id":"r12-12","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Forklar pollineringen og hva som skjer etterpå.","b":"Pollen overføres med vind, vann, insekter eller dyr. Hos dekkfrøede vokser en pollenslange fra arret ned til frøemnet. To hannlige kjønnsceller kommer inn: én befrukter eggcellen og gir en zygote, den andre smelter sammen med sentralkjernen og gir opplagsnæring. Zygoten blir til et plantefoster, og frøet modnes.","u":"kapittel-12.html"},{"id":"r12-13","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Forklar de ulike ukjønnede formeringsmetodene hos dyr, med eksempler.","b":"Todeling hos encellede protister som amøbe. Knoppskyting hos manetenes polypper. Fragmentering hos flatmarker. Partenogenese hos dafnier, bier og komodovaran, der ubefruktede egg utvikler seg til nye individer.","u":"kapittel-12.html"},{"id":"r12-14","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Nevn fordeler og ulemper med ukjønnet formering.","b":"Fordeler: rask populasjonsvekst, ingen energi brukt på å finne partner, og alle individer kan formere seg. Ulemper: liten genetisk variasjon, som gjør populasjonen sårbar for miljøendringer, sykdom og parasitter.","u":"kapittel-12.html"},{"id":"r12-15","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Nevn fordeler og ulemper med kjønnet formering.","b":"Fordeler: stor genetisk variasjon, som gir bedre sjanse for at noen individer tåler endringer. Ulemper: krever energi til kjønnsceller og partnersøk, og bare halvparten av individene føder avkom.","u":"kapittel-12.html"},{"id":"r12-16","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hvorfor sikrer indre befruktning avkommet bedre enn ytre?","b":"Kjønnscellene tørker ikke ut, befruktningen er mer treffsikker, og hos mange arter utvikler fosteret seg beskyttet inne i mor eller i et egg med skall. Derfor trengs færre egg, og overlevelsen per avkom er mye høyere.","u":"kapittel-12.html"},{"id":"r12-17","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Nevn noen dyr som har yngelpleie, og hvilke fordeler det gir.","b":"De fleste fugler og pattedyr, og noen edderkopper, insekter og fisker. Ungene beskyttes mot rovdyr, får mat og lærer å finne føde, fly eller jakte. Det gir høy overlevelse, men koster foreldrene mye energi, og de får derfor færre avkom.","u":"kapittel-12.html"},{"id":"r12-18","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Sammenlikn formeringen hos fugl og pattedyr.","b":"Begge er enkjønnede med indre befruktning og yngelpleie. Fugler legger få egg med kalkskall som ruges ut utenfor kroppen, mens pattedyr har indre fosterutvikling i livmoren og ammer ungene etterpå.","u":"kapittel-12.html"},{"id":"r12-19","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Hvilke kjønnshormoner har kvinner og menn?","b":"Kvinner: østrogen og progesteron fra eggstokkene, i en månedlig syklus. Menn: testosteron fra testiklene, med jevn produksjon. Begge styres av FSH og LH fra hypofysen.","u":"kapittel-12.html"},{"id":"r12-20","n":12,"c":"Kapittel 12","k":"Repetisjon","f":"Forklar produksjonen av sædceller og eggceller.","b":"Sædceller: diploide stamceller i testiklene deler seg ved meiose til fire haploide sædceller, som modnes i bitestikkelen. Produksjonen er kontinuerlig fra puberteten. Eggceller: hvert egganlegg deler seg ved meiose til fire celler, men bare én blir eggcelle – de tre andre fungerer som næring. Egganleggene finnes allerede i fosterlivet.","u":"kapittel-12.html"},{"id":"t13-0","n":13,"c":"Kapittel 13","k":"Begrep","f":"Abiotiske faktorer","b":"Ikke-levende miljøfaktorer: lys, temperatur, vann, pH, næringsstoffer, vind.","u":"kapittel-13.html"},{"id":"t13-1","n":13,"c":"Kapittel 13","k":"Begrep","f":"Biotiske faktorer","b":"Levende miljøfaktorer: mat, konkurranse, predasjon, parasitter, partner.","u":"kapittel-13.html"},{"id":"t13-2","n":13,"c":"Kapittel 13","k":"Begrep","f":"Minimumsfaktor","b":"Den faktoren det er minst av i forhold til behovet, og som begrenser populasjonen.","u":"kapittel-13.html"},{"id":"t13-3","n":13,"c":"Kapittel 13","k":"Begrep","f":"Økologi","b":"Læren om organismenes tilpasninger og samspill med hverandre og miljøet.","u":"kapittel-13.html"},{"id":"t13-4","n":13,"c":"Kapittel 13","k":"Begrep","f":"Populasjon","b":"Alle individer av samme art i et avgrenset område.","u":"kapittel-13.html"},{"id":"t13-5","n":13,"c":"Kapittel 13","k":"Begrep","f":"Samfunn","b":"Alle populasjonene av alle arter i et område.","u":"kapittel-13.html"},{"id":"t13-6","n":13,"c":"Kapittel 13","k":"Begrep","f":"Økosystem","b":"Geografisk avgrenset område med alle abiotiske og biotiske faktorer.","u":"kapittel-13.html"},{"id":"t13-7","n":13,"c":"Kapittel 13","k":"Begrep","f":"Produsent","b":"Autotrof organisme som binder energi, for eksempel planter og alger.","u":"kapittel-13.html"},{"id":"t13-8","n":13,"c":"Kapittel 13","k":"Begrep","f":"Konsument","b":"Heterotrof organisme som spiser andre organismer.","u":"kapittel-13.html"},{"id":"t13-9","n":13,"c":"Kapittel 13","k":"Begrep","f":"Nedbryter","b":"Organisme som lever av dødt organisk materiale, for eksempel sopp og bakterier.","u":"kapittel-13.html"},{"id":"t13-10","n":13,"c":"Kapittel 13","k":"Begrep","f":"Trofisk nivå","b":"Et energinivå i en næringskjede.","u":"kapittel-13.html"},{"id":"t13-11","n":13,"c":"Kapittel 13","k":"Begrep","f":"Næringsnett","b":"Mange næringskjeder som er viklet inn i hverandre.","u":"kapittel-13.html"},{"id":"t13-12","n":13,"c":"Kapittel 13","k":"Begrep","f":"Herbivor","b":"Planteeter.","u":"kapittel-13.html"},{"id":"t13-13","n":13,"c":"Kapittel 13","k":"Begrep","f":"Karnivor","b":"Kjøtteter.","u":"kapittel-13.html"},{"id":"t13-14","n":13,"c":"Kapittel 13","k":"Begrep","f":"Omnivor","b":"Alteter.","u":"kapittel-13.html"},{"id":"t13-15","n":13,"c":"Kapittel 13","k":"Begrep","f":"Parasitt","b":"Organisme som snylter på og tar næring fra en levende vert.","u":"kapittel-13.html"},{"id":"t13-16","n":13,"c":"Kapittel 13","k":"Begrep","f":"Habitat","b":"Levestedet til en art – artens «adresse».","u":"kapittel-13.html"},{"id":"t13-17","n":13,"c":"Kapittel 13","k":"Begrep","f":"Nisje","b":"Alle ressursene arten utnytter og miljøet den er spesialisert for – artens «yrke».","u":"kapittel-13.html"},{"id":"t13-18","n":13,"c":"Kapittel 13","k":"Begrep","f":"Generalist","b":"Art med bred nisje som utnytter mange ressurser.","u":"kapittel-13.html"},{"id":"t13-19","n":13,"c":"Kapittel 13","k":"Begrep","f":"Spesialist","b":"Art med smal nisje og spesielle krav.","u":"kapittel-13.html"},{"id":"t13-20","n":13,"c":"Kapittel 13","k":"Begrep","f":"Gauses prinsipp","b":"To arter kan ikke leve sammen med helt lik nisje og samme begrensende ressurs.","u":"kapittel-13.html"},{"id":"t13-21","n":13,"c":"Kapittel 13","k":"Begrep","f":"Nøkkelart","b":"Art som mange andre arter i økosystemet er avhengige av.","u":"kapittel-13.html"},{"id":"t13-22","n":13,"c":"Kapittel 13","k":"Begrep","f":"Endemisk art","b":"Art som bare finnes innenfor et begrenset område.","u":"kapittel-13.html"},{"id":"t13-23","n":13,"c":"Kapittel 13","k":"Begrep","f":"Spredningskorridor","b":"Sammenhengende naturområde som lar arter bevege seg mellom leveområder.","u":"kapittel-13.html"},{"id":"t13-24","n":13,"c":"Kapittel 13","k":"Begrep","f":"Instinkt","b":"Nedarvet, fast reaksjonsmønster.","u":"kapittel-13.html"},{"id":"t13-25","n":13,"c":"Kapittel 13","k":"Begrep","f":"Refleks","b":"Rask, automatisk respons uten bevisst vurdering.","u":"kapittel-13.html"},{"id":"t13-26","n":13,"c":"Kapittel 13","k":"Begrep","f":"Epigenetikk","b":"Endringer i genaktivitet som skyldes miljø, uten endring i DNA-sekvensen.","u":"kapittel-13.html"},{"id":"r13-0","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Forklar hva som menes med abiotiske og biotiske faktorer.","b":"Abiotiske faktorer er ikke-levende: lys, temperatur, vann, vind, pH, næringsstoffer, berggrunn og forurensning. Biotiske faktorer er levende: mat, konkurranse, predasjon, parasitter, sykdom og partnere.","u":"kapittel-13.html"},{"id":"r13-1","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Hva er en minimumsfaktor?","b":"Den miljøfaktoren det er minst av i forhold til behovet. Den begrenser hvor stor populasjonen kan bli, uansett hvor godt alle andre faktorer er dekket.","u":"kapittel-13.html"},{"id":"r13-2","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Forklar ordene individ, art, populasjon, samfunn og økosystem.","b":"Individ er én organisme. Art er individer som likner hverandre og kan få fruktbart avkom. Populasjon er alle individene av én art i et område. Samfunn er alle populasjonene av alle arter der. Økosystem er samfunnet sammen med alle de abiotiske faktorene.","u":"kapittel-13.html"},{"id":"r13-3","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Hvilke organismer er produsenter?","b":"Autotrofe organismer: planter, alger og blågrønnbakterier, som binder solenergi i fotosyntesen, samt kjemoautotrofe bakterier.","u":"kapittel-13.html"},{"id":"r13-4","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Forklar begrepet trofisk nivå.","b":"Et energinivå i næringskjeden. Produsentene er nivå 1, førstekonsumentene nivå 2, og så videre. Fra ett nivå til det neste tapes opptil nitti prosent av energien, hovedsakelig som varme.","u":"kapittel-13.html"},{"id":"r13-5","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"I hvilke grupper deler vi de heterotrofe organismene?","b":"Herbivore (planteetere), karnivore (kjøttetere), omnivore (altetere) og parasitter.","u":"kapittel-13.html"},{"id":"r13-6","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Hvorfor er det få trofiske nivåer i en næringskjede?","b":"Fordi opptil nitti prosent av energien tapes for hvert nivå. Etter fire–fem nivåer er det ikke nok energi igjen til å forsørge en bestand.","u":"kapittel-13.html"},{"id":"r13-7","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Forklar de tre nivåene av biologisk mangfold.","b":"Gennivå: genetisk variasjon innenfor hver art og mellom populasjoner. Artsnivå: antall arter og hvordan de er avgrenset. Økosystemnivå: mangfoldet av ulike livsmiljøer og naturtyper.","u":"kapittel-13.html"},{"id":"r13-8","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Hva er en nøkkelart? Gi eksempler.","b":"En art som mange andre arter er avhengige av, slik at endringer i bestanden får store følger for hele økosystemet. Eksempler er lemen i fjellet, lodde i havet og barkbiller i skogen.","u":"kapittel-13.html"},{"id":"r13-9","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Forklar ordene habitat og nisje.","b":"Habitatet er levestedet – hvor arten finnes. Nisjen er summen av ressursene arten utnytter og de miljøkravene den har – hvordan den lever.","u":"kapittel-13.html"},{"id":"r13-10","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Hvorfor kan ikke to arter i samme økosystem ha helt like nisjer?","b":"Fordi de da konkurrerer om nøyaktig den samme begrensende ressursen. Den ene arten vil være litt mer effektiv og utkonkurrere den andre – Gauses prinsipp.","u":"kapittel-13.html"},{"id":"r13-11","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Forklar forskjellen på en generalist og en spesialist, og gi eksempler.","b":"En generalist utnytter mange ressurser og lever i mange miljøer, som kråka. En spesialist har smale krav, som lushatthumla, som nesten bare henter nektar fra tyrihjelm. Spesialister er langt mer sårbare for endringer.","u":"kapittel-13.html"},{"id":"r13-12","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Hvilke mønstre har det biologiske mangfoldet på land?","b":"Størst rundt ekvator og avtakende mot polene, og større i lavlandet enn i fjellet. Det skyldes temperatur, produksjon og at tropiske områder har vært stabile mye lenger.","u":"kapittel-13.html"},{"id":"r13-13","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Hvordan varierer mangfoldet i havet?","b":"Varme, åpne havområder har ofte lav produksjon, mens kalde kystområder med oppstrømming av næringsrikt vann er svært produktive og artsrike. Korallrevene er de rikeste områdene.","u":"kapittel-13.html"},{"id":"r13-14","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Hvorfor er spredningskorridorer viktige?","b":"De gjør at individer kan bevege seg mellom leveområder. Da unngår man isolerte småpopulasjoner med innavl, og arter kan reetablere seg etter lokale utdøinger eller flytte seg når klimaet endrer seg.","u":"kapittel-13.html"},{"id":"r13-15","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Gi en kort forklaring på hva atferd er.","b":"Alt fra umiddelbare reflekser og nedarvede instinkter til sinnsstemninger og sammensatt atferd som vandringer, paringsritualer og sosialt samspill.","u":"kapittel-13.html"},{"id":"r13-16","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Hvorfor er det viktig med både nedarvet og tillært atferd?","b":"Nedarvet atferd gir riktig respons med en gang, uten erfaring, og er avgjørende i farlige situasjoner. Læring gjør at individet kan tilpasse seg forhold som varierer, og som evolusjonen ikke kan forutse.","u":"kapittel-13.html"},{"id":"r13-17","n":13,"c":"Kapittel 13","k":"Repetisjon","f":"Gi et eksempel på et nedarvet instinkt hos mennesket.","b":"Vi skvetter av brå lyder, blunker når noe kommer mot øyet, og mange får panikkfølelse ved synet av slanger eller edderkopper. Slike reaksjoner krever ingen læring.","u":"kapittel-13.html"},{"id":"t14-0","n":14,"c":"Kapittel 14","k":"Begrep","f":"Nytteverdi","b":"Naturens verdi vurdert ut fra nytten for mennesker.","u":"kapittel-14.html"},{"id":"t14-1","n":14,"c":"Kapittel 14","k":"Begrep","f":"Egenverdi","b":"Naturens verdi i kraft av å eksistere, uavhengig av nytte.","u":"kapittel-14.html"},{"id":"t14-2","n":14,"c":"Kapittel 14","k":"Begrep","f":"Antroposentrisk natursyn","b":"Natursyn der mennesket er målestokken.","u":"kapittel-14.html"},{"id":"t14-3","n":14,"c":"Kapittel 14","k":"Begrep","f":"Biosentrisk natursyn","b":"Natursyn der alt levende har verdi i seg selv.","u":"kapittel-14.html"},{"id":"t14-4","n":14,"c":"Kapittel 14","k":"Begrep","f":"Naturmangfoldloven","b":"Norsk lov fra 2009 som skal sikre vern og bærekraftig bruk av naturen.","u":"kapittel-14.html"},{"id":"t14-5","n":14,"c":"Kapittel 14","k":"Begrep","f":"Bærekraftig bruk","b":"Bruk som dekker dagens behov uten å ødelegge for kommende generasjoner.","u":"kapittel-14.html"},{"id":"t14-6","n":14,"c":"Kapittel 14","k":"Begrep","f":"Suksesjon","b":"Endring av artssammensetningen i et område over tid.","u":"kapittel-14.html"},{"id":"t14-7","n":14,"c":"Kapittel 14","k":"Begrep","f":"Primærsuksesjon","b":"Suksesjon på nytt land uten jord og frø fra før.","u":"kapittel-14.html"},{"id":"t14-8","n":14,"c":"Kapittel 14","k":"Begrep","f":"Sekundærsuksesjon","b":"Suksesjon der det finnes jord, frø og overlevende organismer.","u":"kapittel-14.html"},{"id":"t14-9","n":14,"c":"Kapittel 14","k":"Begrep","f":"Pionérart","b":"Art som etablerer seg først, vokser og sprer seg raskt.","u":"kapittel-14.html"},{"id":"t14-10","n":14,"c":"Kapittel 14","k":"Begrep","f":"Klimaksfase","b":"Det stabile sluttsamfunnet i en suksesjon.","u":"kapittel-14.html"},{"id":"t14-11","n":14,"c":"Kapittel 14","k":"Begrep","f":"Fragmentering","b":"Oppsplitting av leveområder i små, isolerte biter.","u":"kapittel-14.html"},{"id":"t14-12","n":14,"c":"Kapittel 14","k":"Begrep","f":"Monokultur","b":"Intensiv dyrking av én art på samme areal over tid.","u":"kapittel-14.html"},{"id":"t14-13","n":14,"c":"Kapittel 14","k":"Begrep","f":"Vekstskifte","b":"Å variere hvilken vekst som dyrkes på et areal fra år til år.","u":"kapittel-14.html"},{"id":"t14-14","n":14,"c":"Kapittel 14","k":"Begrep","f":"Konsekvensanalyse","b":"Kartlegging av hvilke følger et tiltak får for miljø, natur og samfunn.","u":"kapittel-14.html"},{"id":"t14-15","n":14,"c":"Kapittel 14","k":"Begrep","f":"Føre-var-prinsippet","b":"Er man usikker på følgene av et inngrep, skal tvilen komme naturen til gode.","u":"kapittel-14.html"},{"id":"t14-16","n":14,"c":"Kapittel 14","k":"Begrep","f":"Rødliste","b":"Oversikt over arter eller naturtyper som står i fare for å forsvinne.","u":"kapittel-14.html"},{"id":"t14-17","n":14,"c":"Kapittel 14","k":"Begrep","f":"Fremmed art","b":"Art som ikke hører naturlig hjemme i området, men er innført av mennesker.","u":"kapittel-14.html"},{"id":"t14-18","n":14,"c":"Kapittel 14","k":"Begrep","f":"Nasjonalpark","b":"Stor verneform med strenge regler mot inngrep.","u":"kapittel-14.html"},{"id":"t14-19","n":14,"c":"Kapittel 14","k":"Begrep","f":"Naturreservat","b":"Mindre verneområde med de strengeste reglene.","u":"kapittel-14.html"},{"id":"t14-20","n":14,"c":"Kapittel 14","k":"Begrep","f":"Landskapsvernområde","b":"Svakeste områdevern; forbyr inngrep som endrer landskapets karakter.","u":"kapittel-14.html"},{"id":"t14-21","n":14,"c":"Kapittel 14","k":"Begrep","f":"Klimagass","b":"Gass som reflekterer varmestråling tilbake mot jorda, for eksempel CO₂, metan og vanndamp.","u":"kapittel-14.html"},{"id":"t14-22","n":14,"c":"Kapittel 14","k":"Begrep","f":"Havforsuring","b":"Synkende pH i havet fordi CO₂ løses i vann og danner karbonsyre.","u":"kapittel-14.html"},{"id":"t14-23","n":14,"c":"Kapittel 14","k":"Begrep","f":"Selvforsterkende prosess","b":"Klimaendring som setter i gang prosesser som forsterker endringen ytterligere.","u":"kapittel-14.html"},{"id":"t14-24","n":14,"c":"Kapittel 14","k":"Begrep","f":"Klimatilpasning","b":"Tiltak som reduserer skadene av klimaendringer, for eksempel å bevare myr.","u":"kapittel-14.html"},{"id":"r14-0","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Nevn noen årsaker til at natur er viktig for mennesker.","b":"Naturen gir mat, rent vann, materialer, medisiner og energi, og økosystemtjenester som pollinering, vannrensing og flomdemping. Den har også stor betydning for folkehelsa, for opplevelser og rekreasjon, og som inspirasjon for kunst og kultur.","u":"kapittel-14.html"},{"id":"r14-1","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Forklar forskjellen på naturens nytteverdi og egenverdi.","b":"Nytteverdien vurderes ut fra hva naturen gir oss – økonomisk, helsemessig eller estetisk. Egenverdien er verdien naturen har i kraft av å eksistere, uavhengig av om vi har nytte av den eller ikke.","u":"kapittel-14.html"},{"id":"r14-2","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hva er formålet med naturmangfoldloven?","b":"Å sikre vern og bærekraftig bruk av naturen, slik at arter, naturtyper og økologiske prosesser bevares. Loven slår fast at naturen har egenverdi, og inneholder føre-var-prinsippet og reglene om områdevern.","u":"kapittel-14.html"},{"id":"r14-3","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hvorfor skjer det hele tiden naturlige forandringer i økosystemene?","b":"Fordi abiotiske forhold varierer og hendelser som brann, ras, flom og stormfelling endrer livsvilkårene. Da forsvinner noen arter, mens andre får muligheter, og artssammensetningen endres.","u":"kapittel-14.html"},{"id":"r14-4","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Forklar ordet suksesjon.","b":"Endringen av artssammensetningen i et område over tid, fra pionérarter via en artsrik konsolideringsfase til et stabilt klimakssamfunn.","u":"kapittel-14.html"},{"id":"r14-5","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Forklar forskjellen på primær- og sekundærsuksesjon.","b":"Primærsuksesjon starter der det ikke fantes liv, jord eller frø fra før, for eksempel på bar stein etter at en isbre har trukket seg tilbake, og tar svært lang tid. Sekundærsuksesjon starter der det allerede finnes jord, frøbank og overlevende organismer, for eksempel etter skogbrann eller hogst, og går raskere.","u":"kapittel-14.html"},{"id":"r14-6","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hva kjennetegner en pionérart? Gi to eksempler.","b":"Den etablerer seg først, vokser og sprer seg raskt, og utnytter gjerne næring som er frigjort. Geitrams og brennesle er eksempler etter skogbrann, der mye nitrogen frigjøres.","u":"kapittel-14.html"},{"id":"r14-7","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hvorfor er arealendring regnet som den viktigste trusselen mot biologisk mangfold?","b":"Fordi leveområder bygges ned, dyrkes opp eller splittes opp. Da mister artene habitatene sine, populasjonene blir små og isolerte, og både genetisk variasjon og artsmangfold synker.","u":"kapittel-14.html"},{"id":"r14-8","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hva er fragmentering, og hvilke problemer gir den?","b":"At leveområder splittes i mindre, isolerte biter av veier, hyttefelt og utbygging. Populasjonene blir små, det genetiske mangfoldet synker, innavl øker, og bestanden tåler tilfeldige hendelser dårligere. Uten spredningskorridorer kan lokale bestander dø ut.","u":"kapittel-14.html"},{"id":"r14-9","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hvorfor er monokultur mer skadelig enn vekstskifte?","b":"Monokultur fjerner mange økologiske nisjer, slik at mangfoldet synker. Skadedyr og sykdommer som er tilpasset denne ene arten, får svært gode vilkår, og behovet for sprøytemidler og gjødsel øker. Vekstskifte og polykultur gir mer variasjon og bedre jordhelse.","u":"kapittel-14.html"},{"id":"r14-10","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Forklar begrepet selvforsterkende prosess.","b":"En klimaendring setter i gang prosesser som forsterker endringen ytterligere. Mindre is gir mørkere overflate som tar opp mer varme, som gir raskere issmelting. Høyere temperatur gir mer vanndamp, som er en klimagass og gir mer oppvarming.","u":"kapittel-14.html"},{"id":"r14-11","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hvorfor foretar vi klimatilpasningstiltak? Nevn to eksempler.","b":"Fordi klimaendringene skjer uansett, og skadene må begrenses. Eksempler: bevare og restaurere myr, som demper flom og lagrer karbon, og pløye om våren i stedet for om høsten, slik at plantedekket hindrer erosjon ved kraftig nedbør.","u":"kapittel-14.html"},{"id":"r14-12","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hvilket departement har det overordnede ansvaret for miljøforvaltningen?","b":"Klima- og miljødepartementet, som blant annet forvalter naturmangfoldloven og forurensningsloven. I hvert fylke har statsforvalterens miljøvernavdeling ansvaret lokalt.","u":"kapittel-14.html"},{"id":"r14-13","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hva er en konsekvensanalyse, og hva er hensikten?","b":"En utredning av hvilke følger et tiltak får for miljø, naturressurser, kulturminner og samfunn. Hensikten er at beslutningen skal tas på et faglig grunnlag, slik at utbyggingen kan stanses eller justeres hvis skadene blir for store.","u":"kapittel-14.html"},{"id":"r14-14","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Forklar føre-var-prinsippet og bærekraftig bruk.","b":"Føre-var-prinsippet: er man usikker på følgene av et inngrep, skal tvilen komme naturen til gode. Bærekraftig bruk: vi kan høste av naturen, men innenfor den økologiske tålegrensen, slik at mangfoldet og ressursgrunnlaget består også for kommende generasjoner.","u":"kapittel-14.html"},{"id":"r14-15","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hvem utarbeider Norsk rødliste, og hva er hensikten?","b":"Artsdatabanken, i samarbeid med forskere og artseksperter. Hensikten er å gi et faglig grunnlag for forvaltning og arealplanlegging, og å spre kunnskap om hvilke arter og naturtyper som er truet.","u":"kapittel-14.html"},{"id":"r14-16","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hva er fremmedartslista?","b":"Artsdatabankens oversikt over fremmede arter i Norge og risikoen de utgjør. Over 3000 fremmede arter er påvist, og 1485 er vurdert å utgjøre en risiko. Høyrisikoarter sprer seg raskt og utkonkurrerer stedegne arter.","u":"kapittel-14.html"},{"id":"r14-17","n":14,"c":"Kapittel 14","k":"Repetisjon","f":"Hvilke fire verneformer er de viktigste, og hva skiller dem?","b":"Nasjonalpark: store områder med strenge regler mot inngrep. Naturreservat: mindre områder med de strengeste reglene, der skjøtsel kan tillates. Landskapsvernområde: svakest vern, forbyr inngrep som endrer landskapets karakter. Prioriterte arter og utvalgte naturtyper: vern av selve arten eller naturtypen, med egen handlingsplan.","u":"kapittel-14.html"}];